export enum AppMode {
  ORACLE = 'ORACLE',   // Chat, Search, Maps, Thinking
  ARTISAN = 'ARTISAN', // Image Gen/Edit, Video Gen
  SEER = 'SEER',       // Image/Video Analysis
  VOICE = 'VOICE'      // Live API, TTS, Transcription
}

export interface ChatMessage {
  role: 'user' | 'model' | 'system';
  text: string;
  timestamp: number;
  sources?: Array<{ web?: { uri: string; title: string }; maps?: { uri: string; title: string } }>;
  isThinking?: boolean;
}

export interface GeneratedAsset {
  type: 'image' | 'video';
  url: string;
  prompt: string;
  id: string;
  timestamp: number;
}

import { GoogleGenAI, Type, Modality, GenerateContentResponse } from "@google/genai";

// Base helper for image/video processing
export const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

export const decodeBase64 = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export const decodeAudioData = async (
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

export const encodeAudio = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export class OmoikaneService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  // Ensure fresh instance if key selection logic is used
  private getFreshAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  // 1. Chat with Thinking / Search / Maps
  async generateText(params: {
    prompt: string;
    model?: string;
    useSearch?: boolean;
    useMaps?: boolean;
    useThinking?: boolean;
    location?: { latitude: number; longitude: number };
  }) {
    const modelName = params.useThinking 
      ? 'gemini-3-pro-preview' 
      : (params.useMaps ? 'gemini-2.5-flash' : 'gemini-3-flash-preview');

    const config: any = {};
    if (params.useThinking) {
      config.thinkingConfig = { thinkingBudget: 32768 };
    }

    const tools: any[] = [];
    if (params.useSearch) tools.push({ googleSearch: {} });
    if (params.useMaps) tools.push({ googleMaps: {} });
    if (tools.length > 0) config.tools = tools;

    if (params.useMaps && params.location) {
      config.toolConfig = {
        retrievalConfig: {
          latLng: {
            latitude: params.location.latitude,
            longitude: params.location.longitude
          }
        }
      };
    }

    const response = await this.ai.models.generateContent({
      model: modelName,
      contents: params.prompt,
      config
    });

    return response;
  }

  // 2. High-Quality Image Generation (Gemini 3 Pro)
  async generateImage(prompt: string, aspectRatio: string = "1:1", size: string = "1K") {
    const ai = this.getFreshAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: {
          aspectRatio,
          imageSize: size as any
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  }

  // 3. Image Editing (Gemini 2.5 Flash Image)
  async editImage(base64Image: string, prompt: string, mimeType: string = 'image/png') {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType } },
          { text: prompt }
        ]
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  }

  // 4. Video Generation (Veo)
  async generateVideo(prompt: string, aspectRatio: "16:9" | "9:16" = "16:9", base64Image?: string) {
    const ai = this.getFreshAI();
    const payload: any = {
      model: 'veo-3.1-fast-generate-preview',
      prompt,
      config: {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio
      }
    };

    if (base64Image) {
      payload.image = {
        imageBytes: base64Image,
        mimeType: 'image/png'
      };
    }

    let operation = await ai.models.generateVideos(payload);
    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  // 5. Image/Video Analysis
  async analyzeMedia(mediaBase64: string, prompt: string, mimeType: string) {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: mediaBase64, mimeType } },
          { text: prompt }
        ]
      }
    });
    return response.text;
  }

  // 6. Text-to-Speech
  async generateSpeech(text: string, voiceName: string = 'Kore') {
    const response = await this.ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName },
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  }
}

export const omoikane = new OmoikaneService();

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppMode } from './types';
import Sidebar from './components/Sidebar';
import Oracle from './components/Oracle';
import Artisan from './components/Artisan';
import Seer from './components/Seer';
import Voice from './components/Voice';

const App: React.FC = () => {
  const [activeMode, setActiveMode] = useState<AppMode>(AppMode.ORACLE);
  const [hasKey, setHasKey] = useState(false);

  // Check for specialized key selection required by Veo/Pro Image models
  useEffect(() => {
    const checkKey = async () => {
      if (typeof window.aistudio?.hasSelectedApiKey === 'function') {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      } else {
        // Fallback for environment where this isn't available
        setHasKey(true);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    if (typeof window.aistudio?.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setHasKey(true); // Assume success per guidelines
    }
  };

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-[#030712] text-gray-100 overflow-hidden font-display">
        <Sidebar activeMode={activeMode} onModeChange={setActiveMode} />

        <main className="flex-1 relative flex flex-col overflow-hidden">
          {!hasKey && (
            <div className="absolute inset-0 z-50 glass flex flex-col items-center justify-center p-6 text-center">
              <div className="max-w-md bg-gray-900/80 p-8 rounded-2xl border border-blue-500/30 shadow-2xl">
                <h2 className="text-2xl font-bold mb-4 text-blue-400">Initialize Omoikane</h2>
                <p className="mb-6 text-gray-400">
                  To access High-Quality Image and Video generation, you must select a Gemini API key from a paid Google Cloud project.
                </p>
                <button
                  onClick={handleOpenKeySelector}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-semibold transition-all shadow-lg hover:shadow-blue-500/20 mb-4 w-full"
                >
                  Select API Key
                </button>
                <a 
                  href="https://ai.google.dev/gemini-api/docs/billing" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="text-xs text-gray-500 hover:text-blue-400 underline"
                >
                  Learn about Gemini API billing
                </a>
              </div>
            </div>
          )}

          <Routes>
            <Route path="/oracle" element={<Oracle />} />
            <Route path="/artisan" element={<Artisan />} />
            <Route path="/seer" element={<Seer />} />
            <Route path="/voice" element={<Voice />} />
            <Route path="*" element={<Navigate to="/oracle" />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

