import React, { useState, useEffect, useRef } from 'react';
import { omoikane, decodeBase64, decodeAudioData, encodeAudio } from '../services/gemini';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';

const Voice: React.FC = () => {
  const [isLive, setIsLive] = useState(false);
  const [transcriptions, setTranscriptions] = useState<string[]>([]);
  const [loadingTTS, setLoadingTTS] = useState(false);
  const [ttsText, setTtsText] = useState('');

  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  // Initialize contexts
  useEffect(() => {
    return () => {
      stopLive();
    };
  }, []);

  const stopLive = () => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    setIsLive(false);
    for (const source of sourcesRef.current) {
      source.stop();
    }
    sourcesRef.current.clear();
  };

  const startLive = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setIsLive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const b64 = encodeAudio(new Uint8Array(int16.buffer));

              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: { data: b64, mimeType: 'audio/pcm;rate=16000' } });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Handle Transcriptions
            if (msg.serverContent?.outputTranscription) {
              setTranscriptions(prev => [...prev, `Omoikane: ${msg.serverContent!.outputTranscription!.text}`]);
            } else if (msg.serverContent?.inputTranscription) {
              setTranscriptions(prev => [...prev, `You: ${msg.serverContent!.inputTranscription!.text}`]);
            }

            // Handle Audio Output
            const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64) {
              const bytes = decodeBase64(base64);
              const buffer = await decodeAudioData(bytes, outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);

              const startTime = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              source.start(startTime);
              nextStartTimeRef.current = startTime + buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }

            if (msg.serverContent?.interrupted) {
              for (const s of sourcesRef.current) s.stop();
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => { console.error('Live error:', e); stopLive(); },
          onclose: () => { stopLive(); }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: 'You are Omoikane, a wise and friendly Japanese deity of intelligence. Speak clearly and helpfully.'
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error(err);
      alert('Failed to start microphone session.');
    }
  };

  const handleTTS = async () => {
    if (!ttsText.trim() || loadingTTS) return;
    setLoadingTTS(true);
    try {
      const base64 = await omoikane.generateSpeech(ttsText);
      if (base64) {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const bytes = decodeBase64(base64);
        const buffer = await decodeAudioData(bytes, ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingTTS(false);
    }
  };

  return (
    <div className="flex flex-col h-full max-w-5xl mx-auto w-full p-4 md:p-8 overflow-hidden">
      <header className="mb-8">
        <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-400">The Voice</h1>
        <p className="text-gray-400 text-sm">Real-time Audio conversation & TTS</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 flex-1 overflow-hidden">
        {/* Live Interface */}
        <div className="flex flex-col gap-6 overflow-hidden">
          <div className={`flex-1 glass rounded-3xl p-8 border ${isLive ? 'border-blue-500 shadow-lg shadow-blue-500/10' : 'border-gray-800'} transition-all flex flex-col items-center justify-center text-center`}>
            <div className={`w-32 h-32 rounded-full mb-8 flex items-center justify-center transition-all ${isLive ? 'bg-blue-600 animate-pulse scale-110 shadow-xl shadow-blue-500/30' : 'bg-gray-800'}`}>
              <svg className={`w-16 h-16 ${isLive ? 'text-white' : 'text-gray-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            </div>

            <h2 className="text-xl font-bold mb-2">{isLive ? 'Live Conversation Active' : 'Start Voice Interface'}</h2>
            <p className="text-gray-500 text-sm mb-8 px-8 leading-relaxed">
              Omoikane will listen to your microphone and respond in real-time with ultra-low latency.
            </p>

            <button
              onClick={isLive ? stopLive : startLive}
              className={`px-12 py-4 rounded-2xl font-bold text-lg transition-all shadow-xl ${
                isLive ? 'bg-red-600 hover:bg-red-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'
              }`}
            >
              {isLive ? 'End Session' : 'Begin Voice Chat'}
            </button>
          </div>

          <div className="glass rounded-3xl p-6 border border-gray-800 flex flex-col h-1/3 min-h-[150px] overflow-hidden">
            <h3 className="text-[10px] font-bold uppercase tracking-widest text-gray-500 mb-3">Live Transcript</h3>
            <div className="flex-1 overflow-y-auto space-y-2 pr-2">
              {transcriptions.length === 0 ? (
                <p className="text-xs text-gray-600 italic">No activity yet...</p>
              ) : (
                transcriptions.map((t, i) => (
                  <div key={i} className={`text-xs p-2 rounded ${t.startsWith('You') ? 'bg-blue-900/10 text-blue-300' : 'bg-gray-800 text-gray-400'}`}>
                    {t}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* TTS & Audio Tools */}
        <div className="glass rounded-3xl border border-gray-800 p-8 flex flex-col gap-8 overflow-hidden">
          <section>
            <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500 mb-6">Text-to-Speech</h3>
            <div className="space-y-4">
              <textarea
                value={ttsText}
                onChange={(e) => setTtsText(e.target.value)}
                placeholder="What should Omoikane say?"
                className="w-full bg-gray-900 border border-gray-700 rounded-xl p-4 text-sm outline-none focus:border-indigo-500 min-h-[180px] resize-none"
              />
              <button
                onClick={handleTTS}
                disabled={loadingTTS || !ttsText.trim()}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-3"
              >
                {loadingTTS ? (
