              </div>
            ) : (
              <div className="space-y-1 animate-in slide-in-from-top-2 duration-300">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => {
                      onLanguageChange(lang);
                      setIsLangExpanded(false);
                    }}
                    className={`w-full flex items-center gap-3 p-2 rounded-lg text-left transition-all border ${
                      currentLanguage.code === lang.code 
                        ? 'bg-blue-600/10 border-blue-500/30 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.1)]' 
                        : 'bg-transparent border-transparent text-gray-500 hover:text-gray-300 hover:bg-white/5'
                    }`}
                  >
                    <span className="text-base leading-none">{lang.flag}</span>
                    <span className="text-xs font-medium tracking-tight">{lang.label}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </nav>

      <div className="p-4 mt-auto">
        <div className="hidden md:block p-4 rounded-2xl bg-gradient-to-br from-gray-800 to-gray-900 border border-gray-700">
          <p className="text-[10px] text-gray-400 leading-relaxed italic">
            {t(currentLanguage.code, 'sidebar.sync_status')}
          </p>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import { omoikane } from '../services/gemini';
import { ChatMessage, Language } from '../types';
import { t } from '../services/i18n';

interface OracleProps {
  language: Language;
}

const Oracle: React.FC<OracleProps> = ({ language }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [settings, setSettings] = useState({
    useSearch: true,
    useMaps: false,
    useThinking: false
  });
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      let location = undefined;
      if (settings.useMaps) {
        const pos = await new Promise<GeolocationPosition>((res, rej) => 
          navigator.geolocation.getCurrentPosition(res, rej)
        );
        location = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
      }

      const response = await omoikane.generateText({
        prompt: `Language preference: ${language.label}. User query: ${input}`,
        useSearch: settings.useSearch,
        useMaps: settings.useMaps,
        useThinking: settings.useThinking,
        location
      });

      const modelMsg: ChatMessage = {
        role: 'model',
        text: response.text || "I couldn't generate a response.",
        timestamp: Date.now(),
        sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
      };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'system', text: 'Error communicating with Omoikane.', timestamp: Date.now() }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full max-w-5xl mx-auto w-full p-4 md:p-8">
      <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-400">{t(language.code, 'oracle.title')}</h1>
          <p className="text-gray-400 text-sm">{t(language.code, 'oracle.desc')}</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <Toggle 
            label={t(language.code, 'oracle.search')} 
            active={settings.useSearch} 
            onClick={() => setSettings(s => ({...s, useSearch: !s.useSearch}))} 
            color="blue"
          />
          <Toggle 
            label={t(language.code, 'oracle.maps')} 
            active={settings.useMaps} 
            onClick={() => setSettings(s => ({...s, useMaps: !s.useMaps}))} 
            color="green"
          />
          <Toggle 
            label={t(language.code, 'oracle.thinking')} 
            active={settings.useThinking} 
            onClick={() => setSettings(s => ({...s, useThinking: !s.useThinking}))} 
            color="purple"
          />
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto mb-6 space-y-6 pr-4">
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-40">
            <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <p className="text-center">{t(language.code, 'oracle.empty')}</p>
          </div>
        )}
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl ${
              msg.role === 'user' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/10' : 
              msg.role === 'system' ? 'bg-red-900/20 text-red-400 border border-red-500/20' : 
              'bg-gray-800 border border-gray-700'
            }`}>
              <div className="text-sm opacity-60 mb-1 flex items-center justify-between">
                <span>{msg.role === 'user' ? 'You' : 'Omoikane'}</span>
                <span>{new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <div className="whitespace-pre-wrap leading-relaxed">{msg.text}</div>
              {msg.sources && msg.sources.length > 0 && (
                <div className="mt-4 pt-4 border-t border-gray-700/50">
                  <p className="text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-2">{t(language.code, 'oracle.sources')}</p>
                  <div className="flex flex-wrap gap-2">
                    {msg.sources.map((chunk: any, si: number) => {
                      const web = chunk.web;
                      const maps = chunk.maps;
                      if (web) return (
                        <a key={si} href={web.uri} target="_blank" rel="noreferrer" className="text-xs px-2 py-1 rounded bg-blue-900/20 text-blue-400 hover:bg-blue-900/40 border border-blue-500/20">
                          {web.title || 'Web Result'}
                        </a>
                      );
                      if (maps) return (
                        <a key={si} href={maps.uri} target="_blank" rel="noreferrer" className="text-xs px-2 py-1 rounded bg-green-900/20 text-green-400 hover:bg-green-900/40 border border-green-500/20">
                          {maps.title || 'Maps Result'}
                        </a>
                      );
                      return null;
                    })}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-gray-800 p-4 rounded-2xl border border-gray-700 flex items-center gap-3">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
              <span className="text-xs text-gray-400 font-medium">{t(language.code, 'oracle.loading')}</span>
            </div>
          </div>
        )}
      </div>

      <div className="relative group">
        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
          placeholder={t(language.code, 'oracle.placeholder')}
          className="w-full bg-gray-800/50 border border-gray-700 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 rounded-2xl p-4 pr-16 min-h-[60px] max-h-[200px] outline-none transition-all resize-none"
        />
        <button
          onClick={handleSend}
          disabled={loading || !input.trim()}
          className="absolute right-4 bottom-4 p-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:bg-gray-700 rounded-xl transition-all shadow-lg"
        >
          <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
          </svg>
        </button>
      </div>
    </div>
  );
};

const Toggle: React.FC<{ label: string, active: boolean, onClick: () => void, color: 'blue' | 'green' | 'purple' }> = ({ label, active, onClick, color }) => {
  const colors = {
    blue: 'bg-blue-600 border-blue-400 text-blue-100',
    green: 'bg-emerald-600 border-emerald-400 text-emerald-100',
    purple: 'bg-purple-600 border-purple-400 text-purple-100'
  };
  return (
    <button
      onClick={onClick}
      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
        active ? colors[color] : 'bg-gray-800 border-gray-700 text-gray-500'
      }`}
    >
      {label}
    </button>
  );
};

export default Oracle;

import React, { useState } from 'react';
import { omoikane, blobToBase64 } from '../services/gemini';
import { GeneratedAsset, Language } from '../types';
import { t } from '../services/i18n';

interface ArtisanProps {
  language: Language;
}

const Artisan: React.FC<ArtisanProps> = ({ language }) => {
  const [assets, setAssets] = useState<GeneratedAsset[]>([]);
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState({
    type: 'image' as 'image' | 'video' | 'edit',
    aspectRatio: '1:1' as any,
    size: '1K' as any,
  });
  const [sourceImage, setSourceImage] = useState<string | null>(null);

  const handleCreate = async () => {
    if (!prompt.trim() && config.type !== 'edit') return;
    setLoading(true);

    try {
      let url: string | null = null;
      if (config.type === 'image') {
        url = await omoikane.generateImage(prompt, config.aspectRatio, config.size);
      } else if (config.type === 'video') {
        url = await omoikane.generateVideo(prompt, config.aspectRatio as any, sourceImage?.split(',')[1]);
      } else if (config.type === 'edit' && sourceImage) {
        url = await omoikane.editImage(sourceImage.split(',')[1], prompt);
      }

      if (url) {
        const newAsset: GeneratedAsset = {
          type: config.type === 'video' ? 'video' : 'image',
          url,
          prompt,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };
        setAssets(prev => [newAsset, ...prev]);
        setPrompt('');
      }
    } catch (err) {
      console.error(err);
      alert('Artisan encountered an error. Please check your project billing or API key settings.');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const b64 = await blobToBase64(file);
      setSourceImage(`data:${file.type};base64,${b64}`);
      if (config.type === 'image') setConfig(c => ({...c, type: 'edit'}));
    }
  };

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto w-full p-4 md:p-8 overflow-hidden">
      <header className="mb-8">
        <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-pink-400 to-orange-400">{t(language.code, 'artisan.title')}</h1>
        <p className="text-gray-400 text-sm">{t(language.code, 'artisan.desc')}</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        <div className="space-y-6 glass p-6 rounded-2xl border border-gray-800 h-fit overflow-y-auto">
          <section>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">{t(language.code, 'artisan.mode')}</label>
            <div className="grid grid-cols-3 gap-2">
              <ModeButton 
                active={config.type === 'image'} 
                onClick={() => setConfig(c => ({...c, type: 'image'}))} 
                icon="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" 
                label={t(language.code, 'artisan.gen')} 
              />
              <ModeButton 
                active={config.type === 'edit'} 
                onClick={() => setConfig(c => ({...c, type: 'edit'}))} 
                icon="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" 
                label={t(language.code, 'artisan.edit')} 
              />
              <ModeButton 
                active={config.type === 'video'} 
                onClick={() => setConfig(c => ({...c, type: 'video'}))} 
                icon="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" 
                label={t(language.code, 'artisan.video')} 
              />
            </div>
          </section>

          {(config.type === 'edit' || config.type === 'video') && (
            <section>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">{t(language.code, 'artisan.source')}</label>
              {sourceImage ? (
                <div className="relative group rounded-xl overflow-hidden aspect-video border border-gray-700">
                  <img src={sourceImage} alt="Source" className="w-full h-full object-cover" />
                  <button 
                    onClick={() => setSourceImage(null)}
                    className="absolute top-2 right-2 p-1.5 bg-red-600 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ) : (
                <div className="relative h-32 border-2 border-dashed border-gray-700 rounded-xl flex items-center justify-center hover:border-blue-500/50 transition-all cursor-pointer">
                  <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
                  <div className="text-center">
                    <svg className="w-8 h-8 text-gray-600 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                    <span className="text-xs text-gray-500 font-medium">{t(language.code, 'artisan.upload')}</span>
                  </div>
                </div>
              )}
            </section>
          )}

          <section>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">{t(language.code, 'artisan.settings')}</label>
            <div className="space-y-4">
              <div>
                <span className="text-[10px] text-gray-500 block mb-1">{t(language.code, 'artisan.aspect_ratio')}</span>
                <select 
                  value={config.aspectRatio} 
                  onChange={(e) => setConfig(c => ({...c, aspectRatio: e.target.value as any}))}
                  className="w-full bg-gray-900 border border-gray-700 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500"
                >
                  <option value="1:1">1:1 Square</option>
                  <option value="16:9">16:9 Landscape</option>
                  <option value="9:16">9:16 Portrait</option>
                  <option value="4:3">4:3 Standard</option>
                  <option value="3:2">3:2 Professional</option>
                </select>
              </div>
              {config.type === 'image' && (
                <div>
                  <span className="text-[10px] text-gray-500 block mb-1">{t(language.code, 'artisan.resolution')}</span>
                  <select 
                    value={config.size} 
                    onChange={(e) => setConfig(c => ({...c, size: e.target.value as any}))}
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500"
                  >
                    <option value="1K">1K Standard</option>
                    <option value="2K">2K High Res</option>
                    <option value="4K">4K Cinematic</option>
                  </select>
                </div>
              )}
            </div>
          </section>

          <section>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">{t(language.code, 'artisan.prompt_label')}</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder={config.type === 'edit' ? t(language.code, 'artisan.edit_placeholder') : t(language.code, 'artisan.prompt_placeholder')}
              className="w-full bg-gray-900 border border-gray-700 rounded-xl p-3 text-sm outline-none focus:border-blue-500 min-h-[100px] resize-none"
            />
          </section>

          <button
            onClick={handleCreate}
            disabled={loading || (!prompt.trim() && config.type !== 'edit')}
            className="w-full py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 disabled:opacity-50 text-white rounded-xl font-bold transition-all shadow-lg shadow-blue-500/10"
          >
            {loading ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                {t(language.code, 'artisan.processing')}
              </span>
            ) : config.type === 'video' ? t(language.code, 'artisan.btn_video') : t(language.code, 'artisan.btn_gen')}
          </button>
        </div>

        <div className="lg:col-span-2 overflow-y-auto space-y-8 pr-2">
          {assets.length === 0 && !loading && (
            <div className="h-full flex flex-col items-center justify-center opacity-30 text-center px-12">
              <svg className="w-20 h-20 mb-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
              <h2 className="text-xl font-bold mb-2">{t(language.code, 'artisan.empty_title')}</h2>
              <p className="text-sm">{t(language.code, 'artisan.empty_desc')}</p>
            </div>
          )}

          {assets.map((asset) => (
            <div key={asset.id} className="glass rounded-3xl overflow-hidden border border-gray-800 shadow-2xl group">
              <div className="relative bg-gray-900/50 min-h-[300px] flex items-center justify-center">
                {asset.type === 'image' ? (
                  <img src={asset.url} alt={asset.prompt} className="max-w-full h-auto object-contain" />
                ) : (
                  <video src={asset.url} controls className="max-w-full h-auto" />
                )}
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-8">
                  <p className="text-sm font-medium mb-4 text-gray-200 line-clamp-3">"{asset.prompt}"</p>
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={() => window.open(asset.url, '_blank')}
                      className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg text-xs font-bold transition-all backdrop-blur"
                    >
                      {t(language.code, 'artisan.open_full')}
                    </button>
                    <span className="text-[10px] text-gray-400 uppercase tracking-widest ml-auto">
                      {new Date(asset.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const ModeButton: React.FC<{ active: boolean, onClick: () => void, icon: string, label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${
      active ? 'bg-blue-600/10 border-blue-500/40 text-blue-400 shadow-lg shadow-blue-500/5' : 'bg-gray-900 border-gray-800 text-gray-500 hover:text-gray-300'
    }`}
  >
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={icon} />
    </svg>
    <span className="text-[10px] font-bold uppercase tracking-widest">{label}</span>
  </button>
);

export default Artisan;

import React, { useState } from 'react';
import { omoikane, blobToBase64 } from '../services/gemini';
import { Language } from '../types';
import { t } from '../services/i18n';

interface SeerProps {
  language: Language;
}

const Seer: React.FC<SeerProps> = ({ language }) => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('Analyze this media in detail. What are the key objects, themes, and activities?');
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const b64 = await blobToBase64(selectedFile);
      setPreview(`data:${selectedFile.type};base64,${b64}`);
      setAnalysis(null);
    }
  };

  const handleAnalyze = async () => {
    if (!file || !preview) return;
    setLoading(true);

    try {
      const base64 = preview.split(',')[1];
      const result = await omoikane.analyzeMedia(base64, prompt, file.type);
      setAnalysis(result || "No analysis generated.");
    } catch (err) {
      console.error(err);
      alert('Analysis failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full max-w-5xl mx-auto w-full p-4 md:p-8">
      <header className="mb-8">
        <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-cyan-400">{t(language.code, 'seer.title')}</h1>
        <p className="text-gray-400 text-sm">{t(language.code, 'seer.desc')}</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 flex-1 overflow-hidden">
        <div className="flex flex-col gap-6 overflow-y-auto pr-2">
          <div className="glass rounded-3xl p-6 border border-gray-800">
            <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500 mb-4">{t(language.code, 'seer.input')}</h3>
