                <>
                  <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  {t(language.code, 'seer.analyzing')}
                </>
              ) : t(language.code, 'seer.btn_analyze')}
            </button>
          </div>
        </div>

        <div className="glass rounded-3xl border border-gray-800 p-8 flex flex-col h-full overflow-hidden">
          <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500 mb-6">{t(language.code, 'seer.log')}</h3>
          <div className="flex-1 overflow-y-auto pr-2">
            {analysis ? (
              <div className="prose prose-invert prose-emerald max-w-none text-gray-200 leading-relaxed whitespace-pre-wrap">
                {analysis}
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center opacity-30 text-center">
                <svg className="w-12 h-12 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <p className="text-sm">{t(language.code, 'seer.empty_log')}</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

