import React, { useState, useEffect, useRef } from 'react';
import { omoikane, decodeBase64, decodeAudioData, encodeAudio, resampleAudio, blobToBase64 } from '../services/gemini';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { Language } from '../types';
import { t } from '../services/i18n';

interface VoiceProps {
  language: Language;
}

const googleSearchTool: FunctionDeclaration = {
  name: 'google_search',
  description: 'Esegue una ricerca mirata su internet per ottenere informazioni aggiornate, news, fatti storici o dati tecnici non presenti nella memoria locale.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      query: {
        type: Type.STRING,
        description: 'La query di ricerca ottimizzata per ottenere i migliori risultati.'
      }
    },
    required: ['query']
  }
};

const Voice: React.FC<VoiceProps> = ({ language }) => {
  const [isLive, setIsLive] = useState(false);
  const [isSharingScreen, setIsSharingScreen] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  const [transcriptions, setTranscriptions] = useState<{role: string, text: string, sources?: any[]}[]>([]);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const transcriptEndRef = useRef<HTMLDivElement>(null);

  const screenStreamRef = useRef<MediaStream | null>(null);
  const screenVideoRef = useRef<HTMLVideoElement | null>(null);
  const screenCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    transcriptEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [transcriptions]);

  useEffect(() => {
    if (isLive) {
      console.log(`Neural recalibration in progress for: ${language.label}`);
    }
  }, [language]);

  useEffect(() => {
    return () => {
      stopLive();
      stopScreenShare();
    };
  }, []);

  const stopScreenShare = () => {
    if (frameIntervalRef.current) {
      window.clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach(track => track.stop());
      screenStreamRef.current = null;
    }
    setIsSharingScreen(false);
  };

  const startScreenShare = async () => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: { frameRate: 5 },
        audio: false
      });
      screenStreamRef.current = stream;
      setIsSharingScreen(true);
      const video = document.createElement('video');
      video.srcObject = stream;
      video.play();
      screenVideoRef.current = video;
      const canvas = document.createElement('canvas');
      screenCanvasRef.current = canvas;
      if (isLive && sessionRef.current) startFrameStreaming();
      stream.getVideoTracks()[0].onended = () => stopScreenShare();
    } catch (err) { console.error("Screen share error:", err); }
  };

  const startFrameStreaming = () => {
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    frameIntervalRef.current = window.setInterval(async () => {
      if (!screenVideoRef.current || !screenCanvasRef.current || !sessionRef.current) return;
      const video = screenVideoRef.current;
      const canvas = screenCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      canvas.width = video.videoWidth / 2;
      canvas.height = video.videoHeight / 2;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      canvas.toBlob(async (blob) => {
        if (blob) {
          const base64Data = await blobToBase64(blob);
          if (sessionRef.current) {
            sessionRef.current.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } });
          }
        }
      }, 'image/jpeg', 0.6);
    }, 1000);
  };

  const stopLive = () => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) {
      window.clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    setIsLive(false);
    setIsSpeaking(false);
    setIsSearching(false);
    for (const source of sourcesRef.current) source.stop();
    sourcesRef.current.clear();
  };

  const startLive = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setIsLive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const resampledData = resampleAudio(inputData, inputCtx.sampleRate, 16000);
              const int16 = new Int16Array(resampledData.length);
              for (let i = 0; i < resampledData.length; i++) {
                int16[i] = Math.max(-1, Math.min(1, resampledData[i])) * 32768;
              }
              const b64 = encodeAudio(new Uint8Array(int16.buffer));
              sessionPromise.then(session => session.sendRealtimeInput({ media: { data: b64, mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
            if (isSharingScreen) startFrameStreaming();
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.toolCall) {
              for (const fc of msg.toolCall.functionCalls) {
                if (fc.name === 'google_search') {
                  setIsSearching(true);
                  try {
                    const searchResult = await omoikane.generateText({
                      prompt: `Search Query in ${language.label}: ${(fc.args as any).query}`,
                      useSearch: true
                    });

                    const sources = searchResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
                    const answer = searchResult.text || "Ricerca completata.";

                    setTranscriptions(prev => [...prev, { 
                      role: 'system', 
                      text: `${t(language.code, 'voice.searching')} "${(fc.args as any).query}"`,
                      sources: sources
                    }]);

                    sessionRef.current?.sendToolResponse({
                      functionResponses: {
                        id: fc.id,
                        name: fc.name,
                        response: { result: answer }
                      }
                    });
                  } catch (e) {
                    console.error("Search Tool Error:", e);
                  } finally {
                    setIsSearching(false);
                  }
                }
              }
            }

            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setTranscriptions(prev => {
                const last = prev[prev.length - 1];
                if (last && last.role === 'omoikane') {
                  return [...prev.slice(0, -1), { ...last, text: last.text + text }];
                }
                return [...prev, { role: 'omoikane', text }];
              });
            } else if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setTranscriptions(prev => {
                const last = prev[prev.length - 1];
                if (last && last.role === 'user') {
                  return [...prev.slice(0, -1), { ...last, text: last.text + text }];
                }
                return [...prev, { role: 'user', text }];
              });
            }

            const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64) {
              setIsSpeaking(true);
              const bytes = decodeBase64(base64);
              const buffer = await decodeAudioData(bytes, outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              const startTime = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              source.start(startTime);
              nextStartTimeRef.current = startTime + buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
            }

            if (msg.serverContent?.interrupted) {
              for (const s of sourcesRef.current) s.stop();
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => { console.error('Live error:', e); stopLive(); },
          onclose: () => stopLive()
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
          tools: [{ functionDeclarations: [googleSearchTool] }],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are Omoikane, the user's personal AI. 
          ABSOLUTE PREROGATIVE: Your system and output language is ${language.label}. 
          You MUST listen with maximum attention to every nuance in ${language.label} and respond exclusively using this language. 
          You are an expert in vision and hearing. You can see the user's screen in real time. 
          YOU HAVE INTERNET ACCESS: if the user asks for things you don't know or that concern recent news/facts, use the google_search function to inform yourself before answering. 
          Interact proactively with what you see on the user's screen. Be quick, wise, and maintain a cyberpunk yet professional style.`
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { alert('Errore di connessione a Omoikane.'); }
  };

  return (
    <div className="flex flex-col h-full w-full bg-[#020617] relative overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-blue-900/10 blur-[120px] rounded-full"></div>
      </div>

      <div className="flex flex-col lg:flex-row h-full w-full p-4 lg:p-8 gap-8 relative z-10">
        <div className="flex-1 flex flex-col items-center justify-center relative">
          <div className="absolute top-0 md:top-4 left-4 flex flex-col gap-4 z-20">
            {isSharingScreen && (
              <div className="w-48 aspect-video rounded-xl overflow-hidden border border-blue-500/50 shadow-2xl group relative bg-black">
                <video autoPlay muted ref={el => { if(el && screenStreamRef.current) el.srcObject = screenStreamRef.current; }} className="w-full h-full object-cover" />
                <div className="absolute bottom-1 right-1 px-1.5 py-0.5 bg-blue-600 rounded text-[8px] font-bold uppercase">Live View</div>
              </div>
            )}
            {isSearching && (
              <div className="bg-cyan-600/20 border border-cyan-500/50 rounded-xl px-4 py-2 flex items-center gap-3 animate-pulse">
                <div className="w-2 h-2 bg-cyan-400 rounded-full"></div>
                <span className="text-[10px] font-bold uppercase tracking-widest text-cyan-400">{t(language.code, 'voice.searching')}</span>
              </div>
            )}
          </div>

          <div className="text-center mb-12">
            <h1 className="text-4xl font-bold font-display tracking-tight text-white mb-2">Omoikane</h1>
            <p className={`text-sm font-medium uppercase tracking-[0.2em] transition-colors duration-500 ${isLive ? 'text-blue-400' : 'text-gray-600'}`}>
              {isLive ? (isSpeaking ? t(language.code, 'voice.status_speaking') : t(language.code, 'voice.status_active')) : t(language.code, 'voice.status_idle')}
            </p>
          </div>

          <div className="relative mb-16">
            <div className={`w-64 h-64 rounded-full flex items-center justify-center transition-all duration-700 relative ${isLive ? 'scale-110' : 'scale-100'}`}>
              <div className={`absolute inset-0 rounded-full border-2 transition-all duration-500 ${isLive ? 'border-blue-500/30 scale-125 animate-ping' : 'border-gray-800'}`}></div>
              <div className={`absolute inset-0 rounded-full border border-blue-400/20 transition-all duration-700 ${isLive ? 'scale-150 opacity-100' : 'scale-100 opacity-0'}`}></div>
              <div className={`w-48 h-48 rounded-full flex items-center justify-center shadow-2xl transition-all duration-500 overflow-hidden ${isLive ? 'bg-gradient-to-br from-cyan-500 to-blue-700 shadow-blue-500/40' : 'bg-gray-900 border border-gray-800'}`}>
                {isSpeaking ? (
                  <div className="flex gap-1.5 items-end h-12">
                    {[1, 2, 3, 4, 5, 6].map(i => (
                      <div key={i} className="w-2 bg-white/90 rounded-full animate-pulse" style={{ height: `${20 + Math.random() * 80}%`, animationDuration: `${0.5 + Math.random()}s` }}></div>
                    ))}
                  </div>
                ) : (
                  <svg className={`w-20 h-20 transition-colors ${isLive ? 'text-white' : 'text-gray-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  </svg>
                )}
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button onClick={isLive ? stopLive : startLive} className={`px-10 py-5 rounded-full font-bold text-lg transition-all ${isLive ? 'bg-red-500/10 border border-red-500/50 text-red-500 hover:bg-red-500 hover:text-white' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-[0_0_30px_rgba(37,99,235,0.4)]'}`}>
              {isLive ? t(language.code, 'voice.btn_sleep') : t(language.code, 'voice.btn_wake')}
            </button>
            <button onClick={isSharingScreen ? stopScreenShare : startScreenShare} className={`px-8 py-5 rounded-full font-bold text-lg border transition-all flex items-center gap-3 ${isSharingScreen ? 'bg-blue-600/20 border-blue-500 text-blue-400' : 'bg-white/5 border-white/10 text-gray-400 hover:bg-white/10'}`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
              {isSharingScreen ? t(language.code, 'voice.btn_view_on') : t(language.code, 'voice.btn_view_off')}
            </button>
          </div>
        </div>

        <div className="w-full lg:w-96 flex flex-col glass rounded-[2rem] border-white/5 overflow-hidden shadow-2xl">
          <div className="p-6 border-b border-white/5 bg-white/5 flex items-center justify-between">
            <h2 className="text-sm font-bold uppercase tracking-widest text-blue-400 flex items-center gap-2">
              <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
              {t(language.code, 'voice.output_title')}
            </h2>
          </div>
          <div className="flex-1 overflow-y-auto p-6 space-y-6 scroll-smooth custom-scrollbar">
            {transcriptions.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center px-4 opacity-20">
                <svg className="w-12 h-12 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
                <p className="text-sm font-medium italic">{t(language.code, 'voice.sync_msg')}</p>
              </div>
            ) : (
              transcriptions.map((msg, i) => (
                <div key={i} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500 mb-1 px-2">
                    {msg.role === 'user' ? 'Input' : (msg.role === 'system' ? 'Neural Link' : 'Omoikane')}
                  </span>
                  <div className={`max-w-[90%] p-4 rounded-2xl text-sm leading-relaxed ${
                    msg.role === 'user' ? 'bg-blue-600/20 text-blue-100 border border-blue-500/30' : 
                    msg.role === 'system' ? 'bg-cyan-600/10 text-cyan-400 border border-cyan-500/20 italic' :
                    'bg-white/5 text-gray-300 border border-white/5 shadow-xl'
                  }`}>
                    {msg.text}
                    {msg.sources && msg.sources.length > 0 && (
                      <div className="mt-3 pt-3 border-t border-cyan-500/20 flex flex-wrap gap-2">
                        {msg.sources.map((s, si) => (
                          <a key={si} href={s.web?.uri} target="_blank" rel="noreferrer" className="text-[10px] bg-cyan-900/30 px-2 py-1 rounded border border-cyan-500/30 text-cyan-200 hover:bg-cyan-900/50 transition-all">
                            {s.web?.title || 'Link'}
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
            <div ref={transcriptEndRef} />
          </div>
          <div className="p-4 bg-white/5 border-t border-white/5 flex items-center justify-between px-6">
            <div className="flex items-center gap-3 text-[10px] text-gray-500 italic">
              {language.flag} {language.label} active.
            </div>
            <span className="text-[10px] text-blue-400 font-bold uppercase tracking-tighter">{t(language.code, 'voice.link_ok')}</span>
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(59,130,246,0.3); }
      `}</style>
    </div>
  );
};

