import React, { useState, useEffect } from 'react';
import { MemoryRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppMode, LANGUAGES, Language } from './types';
import Sidebar from './components/Sidebar';
import Oracle from './components/Oracle';
import Artisan from './components/Artisan';
import Seer from './components/Seer';
import Voice from './components/Voice';

const App: React.FC = () => {
  const [activeMode, setActiveMode] = useState<AppMode>(AppMode.ORACLE);
  const [hasKey, setHasKey] = useState(false);
  const [language, setLanguage] = useState<Language>(LANGUAGES[0]);

  useEffect(() => {
    const checkKey = async () => {
      if (typeof window.aistudio?.hasSelectedApiKey === 'function') {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      } else {
        setHasKey(true);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    if (typeof window.aistudio?.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setHasKey(true);
    }
  };

  return (
    <MemoryRouter initialEntries={['/oracle']}>
      <div className="flex h-screen w-full bg-[#030712] text-gray-100 overflow-hidden font-display">
        <Sidebar 
          activeMode={activeMode} 
          onModeChange={setActiveMode} 
          currentLanguage={language}
          onLanguageChange={setLanguage}
        />

        {/* Main scrollable container with enforced scrollbars for overflow */}
        <main className="flex-1 relative flex flex-col overflow-auto app-scroll-container border-l border-white/5 bg-[#030712]">
          {!hasKey && (
            <div className="absolute inset-0 z-50 glass flex flex-col items-center justify-center p-6 text-center">
              <div className="max-w-md bg-gray-900/80 p-8 rounded-2xl border border-blue-500/30 shadow-2xl">
                <h2 className="text-2xl font-bold mb-4 text-blue-400">Initialize Omoikane</h2>
                <p className="mb-6 text-gray-400">
                  To access High-Quality Image and Video generation, you must select a Gemini API key from a paid Google Cloud project.
                </p>
                <button
                  onClick={handleOpenKeySelector}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-semibold transition-all shadow-lg hover:shadow-blue-500/20 mb-4 w-full"
                >
                  Select API Key
                </button>
                <a 
                  href="https://ai.google.dev/gemini-api/docs/billing" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="text-xs text-gray-500 hover:text-blue-400 underline"
                >
                  Learn about Gemini API billing
                </a>
              </div>
            </div>
          )}

          <div className="min-w-[800px] min-h-full flex flex-col">
            <Routes>
              <Route path="/oracle" element={<Oracle language={language} />} />
              <Route path="/artisan" element={<Artisan language={language} />} />
              <Route path="/seer" element={<Seer language={language} />} />
              <Route path="/voice" element={<Voice language={language} />} />
              <Route path="*" element={<Navigate to="/oracle" replace />} />
            </Routes>
          </div>
        </main>
      </div>
    </MemoryRouter>
  );
};

export default App;

