            </div>
          </div>

          <div className="flex gap-4">
            <button onClick={isLive ? stopLive : startLive} className={`px-10 py-5 rounded-full font-bold text-lg transition-all ${isLive ? 'bg-red-500/10 border border-red-500/50 text-red-500 hover:bg-red-500 hover:text-white' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-[0_0_30px_rgba(37,99,235,0.4)]'}`}>
