import React, { useState, useMemo, useEffect } from 'react';
import TerminalHeader from './components/TerminalHeader';
import DiagnosticTerminal from './components/DiagnosticTerminal';
import RecipeDisplay from './components/RecipeDisplay';
import RecipeChat from './components/RecipeChat';
import { UserDiagnostics, Recipe, AppLanguage, AppTheme } from './types';
import { i18n } from './translations';
import { generateRecipe, createRecipeChat } from './services/geminiService';
import { Chat } from '@google/genai';

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [language, setLanguage] = useState<AppLanguage>('Italiano');
  const [theme, setTheme] = useState<AppTheme>('dark');

  const t = useMemo(() => i18n[language], [language]);

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);

  const handleDiagnosticSubmit = async (data: UserDiagnostics) => {
    setLoading(true);
    setError(null);
    setRecipe(null);
    setChatSession(null);

    try {
      const result = await generateRecipe(data);
      setRecipe(result);
      const session = createRecipeChat(result, data);
      setChatSession(session);

      setTimeout(() => {
        const el = document.getElementById('recipe-output');
        el?.scrollIntoView({ behavior: 'smooth' });
      }, 300);
    } catch (err) {
      setError(t.error);
    } finally {
      setLoading(false);
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <div className="min-h-screen pb-24 theme-transition font-mono selection:bg-white selection:text-black" style={{ color: 'var(--text-color)' }}>
      <TerminalHeader t={t} theme={theme} onThemeToggle={toggleTheme} />

      <main className="container mx-auto px-4 mt-12 space-y-16">
        <div className="max-w-5xl mx-auto">
          <section className="mb-16">
            <DiagnosticTerminal 
              onSumbit={handleDiagnosticSubmit} 
              isLoading={loading} 
              language={language}
              setLanguage={setLanguage}
              t={t}
            />
          </section>

          {error && (
            <div className="p-4 border text-[10px] uppercase mb-12" style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}>
              [SYSTEM_ERROR] {error}
            </div>
          )}

          {loading && !recipe && (
            <div className="flex flex-col items-center justify-center py-24 space-y-8 animate-in fade-in zoom-in duration-500">
              <div className="relative w-24 h-24 flex items-center justify-center">
                {/* Outer dashed ring */}
                <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_8s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>

                {/* Middle ring with gaps */}
                <div className="absolute inset-2 border-t-2 border-b-2 rounded-full animate-[spin_3s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>

                {/* Inner fast ring */}
                <div className="absolute inset-4 border-l-2 border-r-2 rounded-full animate-[spin_1.5s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>

                {/* Central molecular core */}
                <div className="w-4 h-4 rounded-full animate-pulse" style={{ backgroundColor: 'var(--text-color)' }}></div>

                {/* Scanning line effect */}
                <div className="absolute w-full h-0.5 animate-[loading-scan_2s_ease-in-out_infinite] opacity-10" style={{ backgroundColor: 'var(--text-color)' }}></div>
              </div>

              <div className="text-center space-y-2">
                <p className="text-[10px] font-bold tracking-[0.6em] uppercase animate-pulse" style={{ color: 'var(--text-color)' }}>
                  {t.loading}
                </p>
                <p className="text-[8px] opacity-40 uppercase tracking-widest font-mono">
                  Sincronizzazione molecolare in corso...
                </p>
              </div>
            </div>
          )}

          {recipe && (
            <section id="recipe-output" className="pt-20 border-t" style={{ borderColor: 'var(--border-color)' }}>
              <RecipeDisplay recipe={recipe} t={t} />
              {chatSession && <RecipeChat chatSession={chatSession} t={t} />}
              <div className="mt-16 flex justify-center">
                <button 
                  onClick={() => {
                    setRecipe(null);
                    setChatSession(null);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  className="px-8 py-2 border text-[9px] uppercase tracking-widest transition-all opacity-40 hover:opacity-100"
                  style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                >
                  {t.newSynthesis}
                </button>
              </div>
            </section>
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 border-t py-2 px-6 flex justify-between items-center z-40 backdrop-blur-md" style={{ backgroundColor: 'var(--header-bg)', borderColor: 'var(--border-color)' }}>
        <div className="text-[7px] opacity-30 uppercase tracking-widest font-bold" style={{ color: 'var(--text-color)' }}>
          CHEF OMOIKANE // V5.0
        </div>
        <div className="flex gap-4">
          <span className="text-[7px] opacity-60 tracking-widest uppercase" style={{ color: 'var(--text-color)' }}>STABLE</span>
        </div>
      </footer>

      <style>{`
        @keyframes loading-scan {
          0%, 100% { transform: translateY(-30px); opacity: 0; }
          50% { transform: translateY(30px); opacity: 0.3; }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Recipe, Translations } from '../types';

interface Props {
  recipe: Recipe;
  t: Translations;
}

const RecipeDisplay: React.FC<Props> = ({ recipe, t }) => {
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);

  const handleShare = async () => {
    const formattedRecipe = `
# ${recipe.title}
---
**${t.clinicalAnalysis}**
${recipe.medicalAnalysis}

**${t.hardware} (Ingredients)**
${recipe.ingredients.map(ing => `- ${ing.name}: ${ing.amount} (${ing.function})`).join('\n')}

**${t.protocol} (Procedure)**
${recipe.procedure.map((step, idx) => `${idx + 1}. ${step}`).join('\n')}

**${t.telemetry} (Macros)**
- Calories: ${recipe.macros.calories}
- Protein: ${recipe.macros.protein}
- Carbs: ${recipe.macros.carbs}
- Fats: ${recipe.macros.fats}
- Fiber: ${recipe.macros.fiber}

**${t.scienceLog}**
${recipe.scienceCheck}
    `.trim();

    if (navigator.share) {
      try {
        await navigator.share({
          title: recipe.title,
          text: formattedRecipe,
        });
      } catch (err) {
        copyToClipboard(formattedRecipe);
      }
    } else {
      copyToClipboard(formattedRecipe);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setShowCopyFeedback(true);
      setTimeout(() => setShowCopyFeedback(false), 2000);
    });
  };

  return (
    <div className="space-y-12 animate-in fade-in duration-700">
      <div className="glow-border p-6 md:p-10 rounded-none border-t-4 relative overflow-x-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', borderTopColor: 'var(--text-color)' }}>
        <div className="absolute top-4 right-4 md:right-10 flex flex-col items-end gap-2">
          <button 
            onClick={handleShare}
            className="flex items-center gap-2 px-3 py-1.5 border border-white/20 text-[9px] uppercase font-bold tracking-widest hover:bg-white/10 transition-all"
            style={{ color: 'var(--text-color)', borderColor: 'var(--border-color)' }}
