import React, { useState, useMemo, useEffect, useRef } from 'react';
import TerminalHeader from './components/TerminalHeader';
import DiagnosticTerminal from './components/DiagnosticTerminal';
import RecipeDisplay from './components/RecipeDisplay';
import RecipeChat from './components/RecipeChat';
import { UserDiagnostics, Recipe, AppLanguage, AppTheme } from './types';
import { i18n } from './translations';
import { generateRecipe, createRecipeChat } from './services/geminiService';
import { Chat } from '@google/genai';

export const LANGUAGES: { code: AppLanguage; label: string; flag: string; speechCode: string }[] = [
  { code: 'Italiano', label: 'ITALIANO', flag: '🇮🇹', speechCode: 'it-IT' },
  { code: 'English', label: 'ENGLISH', flag: '🇬🇧', speechCode: 'en-US' },
  { code: 'Japanese', label: '日本語', flag: '🇯🇵', speechCode: 'ja-JP' },
  { code: 'Español', label: 'ESPAÑOL', flag: '🇪🇸', speechCode: 'es-ES' },
  { code: 'Chinese', label: '中文', flag: '🇨🇳', speechCode: 'zh-CN' },
  { code: 'Français', label: 'FRANÇAIS', flag: '🇫🇷', speechCode: 'fr-FR' },
];

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [language, setLanguage] = useState<AppLanguage>('Italiano');
  const [theme, setTheme] = useState<AppTheme>('dark');

  const abortControllerRef = useRef<AbortController | null>(null);

  const t = useMemo(() => i18n[language], [language]);

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);

  const handleCancel = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setLoading(false);
    setError(null);
  };

  const handleDiagnosticSubmit = async (data: UserDiagnostics) => {
    setLoading(true);
    setError(null);
    setRecipe(null);
    setChatSession(null);

    // Setup AbortController for cancellation
    abortControllerRef.current = new AbortController();

    try {
      // Note: We're passing the signal to the service, though the Gemini SDK 
      // might require manual handling if it doesn't support signals directly.
      const result = await generateRecipe(data);

      // If we reached here, synthesis was successful
      setRecipe(result);
      const session = createRecipeChat(result, data);
      setChatSession(session);

      setTimeout(() => {
        const el = document.getElementById('recipe-output');
        el?.scrollIntoView({ behavior: 'smooth' });
      }, 300);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Synthesis aborted by user');
      } else {
        setError(t.error);
      }
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <div className="min-h-screen pb-24 theme-transition font-mono selection:bg-white selection:text-black" style={{ color: 'var(--text-color)' }}>
      <TerminalHeader t={t} theme={theme} onThemeToggle={toggleTheme} language={language} setLanguage={setLanguage} />

      <main className="container mx-auto px-4 mt-12 space-y-16">
        <div className="max-w-5xl mx-auto">
          <section className="mb-16">
            <DiagnosticTerminal 
              onSumbit={handleDiagnosticSubmit} 
              isLoading={loading} 
              language={language}
              setLanguage={setLanguage}
              t={t}
            />
          </section>

          {error && (
            <div className="p-4 border text-[10px] uppercase mb-12" style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}>
              [SYSTEM_ERROR] {error}
            </div>
          )}

          {/* Loading Overlay */}
          {loading && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center backdrop-blur-md animate-in fade-in duration-300" 
                 style={{ backgroundColor: theme === 'dark' ? 'rgba(0,0,0,0.85)' : 'rgba(255,255,255,0.85)' }}>

              {/* Cancel Button */}
              <button 
                onClick={handleCancel}
                className="absolute top-8 right-8 w-12 h-12 rounded-full border flex items-center justify-center transition-all hover:scale-110 active:scale-95 group"
                style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                title="CANCEL_SYNTHESIS"
              >
                <span className="text-xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
                <span className="absolute -bottom-6 text-[7px] font-bold tracking-widest opacity-0 group-hover:opacity-100 uppercase">Abort</span>
              </button>

              <div className="flex flex-col items-center space-y-10">
                <div className="relative w-32 h-32 flex items-center justify-center">
                  {/* Outer dashed ring */}
                  <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_8s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>

                  {/* Middle ring with gaps */}
                  <div className="absolute inset-2 border-t-2 border-b-2 rounded-full animate-[spin_3s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>

                  {/* Inner fast ring */}
                  <div className="absolute inset-4 border-l-2 border-r-2 rounded-full animate-[spin_1.5s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>

                  {/* Central molecular core */}
                  <div className="w-6 h-6 rounded-full animate-pulse" style={{ backgroundColor: 'var(--text-color)' }}></div>

                  {/* Scanning line effect */}
                  <div className="absolute w-full h-0.5 animate-[loading-scan_2s_ease-in-out_infinite] opacity-10" style={{ backgroundColor: 'var(--text-color)' }}></div>
                </div>

                <div className="text-center space-y-4 max-w-xs">
                  <div className="space-y-1">
                    <p className="text-[12px] font-bold tracking-[0.8em] uppercase animate-pulse pr-[-0.8em]" style={{ color: 'var(--text-color)' }}>
                      {t.loading}
                    </p>
                    <div className="h-0.5 w-full bg-white/10 relative overflow-hidden">
                      <div className="absolute inset-0 bg-current animate-[loading-progress_3s_ease-in-out_infinite]"></div>
                    </div>
                  </div>
                  <p className="text-[9px] opacity-40 uppercase tracking-[0.2em] font-mono leading-relaxed">
                    Sincronizzazione matrici molecolari...<br/>
                    Analisi parametri clinici in corso...
                  </p>
                </div>
              </div>
            </div>
          )}

          {recipe && (
            <section id="recipe-output" className="pt-20 border-t" style={{ borderColor: 'var(--border-color)' }}>
              <RecipeDisplay recipe={recipe} t={t} />
              {chatSession && <RecipeChat chatSession={chatSession} t={t} />}
              <div className="mt-16 flex justify-center">
                <button 
                  onClick={() => {
                    setRecipe(null);
                    setChatSession(null);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  className="px-8 py-2 border text-[9px] uppercase tracking-widest transition-all opacity-40 hover:opacity-100"
                  style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                >
                  {t.newSynthesis}
                </button>
              </div>
            </section>
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 border-t py-2 px-6 flex justify-between items-center z-40 backdrop-blur-md" style={{ backgroundColor: 'var(--header-bg)', borderColor: 'var(--border-color)' }}>
        <div className="text-[7px] opacity-30 uppercase tracking-widest font-bold" style={{ color: 'var(--text-color)' }}>
          CHEF OMOIKANE // V5.0
        </div>
        <div className="flex gap-4">
          <span className="text-[7px] opacity-60 tracking-widest uppercase" style={{ color: 'var(--text-color)' }}>STABLE</span>
        </div>
      </footer>

      <style>{`
        @keyframes loading-scan {
          0%, 100% { transform: translateY(-40px); opacity: 0; }
          50% { transform: translateY(40px); opacity: 0.3; }
        }
        @keyframes loading-progress {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
      `}</style>
    </div>
  );
};

