            </svg>
            {t.shareBtn}
          </button>
          {showCopyFeedback && (
            <span className="text-[7px] font-bold tracking-tighter opacity-80" style={{ color: 'var(--text-color)' }}>
              {t.copySuccess}
            </span>
          )}
        </div>

        <h2 className="header-font text-2xl md:text-4xl font-black mb-6 tracking-tighter uppercase italic leading-tight pr-24 md:pr-32" style={{ color: 'var(--text-color)' }}>
          {recipe.title}
