import React, { useState, useRef, useCallback } from 'react';
import { Translations, UserDiagnostics, ChatMessage } from '../types';
import { analyzeHealthOrMenu } from '../services/geminiService';

interface Props {
  t: Translations;
  diagnostics: UserDiagnostics;
}

const QuestionTerminal: React.FC<Props> = ({ t, diagnostics }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const handleSend = async (image?: string) => {
    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      const response = await analyzeHealthOrMenu(query, diagnostics, image);
      setMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "ERRORE CRITICO: Canale di comunicazione interrotto." }]);
    } finally {
      setIsProcessing(false);
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const startVoiceInput = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;

    const recognition = new SpeechRecognition();
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev ? `${prev} ${transcript}` : transcript);
    };
    recognition.start();
  }, []);

  return (
    <div className="glow-border flex flex-col min-h-[500px] h-[70vh] rounded-none overflow-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
      <div className="border-b p-4 flex justify-between items-center" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
        <h2 className="header-font text-xs font-bold tracking-[0.2em] uppercase" style={{ color: 'var(--text-color)' }}>
          {t.healthCenter}
        </h2>
        <div className="flex gap-2">
           <button 
             onClick={() => fileInputRef.current?.click()}
             className="px-3 py-1 border text-[8px] font-bold uppercase hover:bg-white/10 transition-all flex items-center gap-2"
             style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
           >
             <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
             </svg>
             {t.uploadMenu}
           </button>
           <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleFileUpload} />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 font-mono custom-scrollbar">
        {messages.length === 0 && (
          <div className="text-[10px] opacity-30 italic">
            // UNIT_OMOIKANE IN ASCOLTO...<br/>
            // CHIEDI CONSIGLI SULLA SALUTE O SCANSIONA UN MENU PER ANALISI BIOCHIMICA.
          </div>
        )}
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 border ${msg.role === 'user' ? 'bg-white text-black' : ''}`} style={{ borderColor: 'var(--border-color)' }}>
              <div className="text-[7px] uppercase font-bold mb-2 opacity-50 border-b pb-1">
                {msg.role === 'user' ? 'UNIT_PILOT' : 'CHEF_OMOIKANE'}
              </div>
              {msg.image && (
                <img src={msg.image} alt="Menu" className="mb-4 max-w-full border p-1" style={{ borderColor: 'var(--border-color)' }} />
              )}
              <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.text}</div>
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="animate-pulse text-[9px] uppercase tracking-widest opacity-50 px-2 py-1 bg-white/5 border border-white/10 w-fit">
            {t.processing}
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      <form onSubmit={(e) => { e.preventDefault(); handleSend(); }} className="p-4 border-t flex gap-4" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
        <div className="flex-1 relative flex items-center">
          <span className="mr-3 opacity-30">{'>'}</span>
          <input 
            type="text" 
            className="flex-1 bg-transparent outline-none text-sm font-mono pr-10"
            style={{ color: 'var(--text-color)' }}
            placeholder={t.chatPlaceholder}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={isProcessing}
          />
          <button
            type="button"
            onClick={startVoiceInput}
            className={`absolute right-0 p-2 transition-all ${isListening ? 'recording-pulse' : 'opacity-30 hover:opacity-100'}`}
            style={{ color: 'var(--text-color)' }}
          >
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
            </svg>
          </button>
        </div>
        <button 
          type="submit"
          disabled={isProcessing || !input.trim()}
          className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase hover:bg-opacity-80 disabled:opacity-20 transition-all"
        >
          {t.send}
        </button>
      </form>
    </div>
  );
};

export default QuestionTerminal;

