import { GoogleGenAI, Type, Chat, GenerateContentResponse } from "@google/genai";
import { UserDiagnostics, Recipe } from "../types";
import { i18n } from "../translations";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (lang: string) => {
  const t = i18n[lang as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  return `Sei Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. FORMATO ELENCHI: Ogni volta che presenti un elenco (ingredienti, passaggi, avvisi), scrivi ogni elemento su una NUOVA RIGA, formando una colonna verticale perfetta. Non raggruppare elementi sulla stessa riga.
4. ANALISI CLINICA (IMPORTANTE): Il campo 'medicalAnalysis' deve iniziare con '${safetyHeader}' seguito da un elenco puntato (usa '-') dove ogni punto occupa una nuova riga. Esempio:
   ${safetyHeader}
   - Ingrediente X: [Motivazione medica/sapore]. [Azione intrapresa].
   - Ingrediente Y: [Motivazione]. [Sostituzione].
5. TABELLE: Se usi tabelle, assicurati che siano ben spaziate verticalmente.
6. SPAZIATURA: Usa una riga vuota tra i blocchi di testo per massimizzare la leggibilità.
7. Mantieni un leggero stile tecnico (es. "Protocollo", "Sintesi").
8. Lingua: ${lang}. Rispondi SEMPRE nella lingua dell'utente.

LOGICA DI VALUTAZIONE (CRITICA):
9. COMPATIBILITÀ SAPORI: Se gli ingredienti scelti dall'utente o necessari non si armonizzano bene, informa l'utente in modo visibile (in colonna) che la combinazione è sconsigliata e suggerisci correzioni.
10. SICUREZZA MEDICA E DIETE SPECIFICHE: Se gli ingredienti sono controindicati per la condizione medica (${lang}), le allergie o i REGIMI ALIMENTARI (es. Vegano, Pescateriano, Musulmano/Halal) dell'utente, segnalalo immediatamente con estrema chiarezza.
11. REGIMI SPECIALI:
    - VEGANO: Scarta rigorosamente ogni derivato animale (carne, pesce, latticini, uova, miele).
    - PESCATARIANO: Scarta carne ma accetta pesce e frutti di mare.
    - MUSULMANO: Scarta rigorosamente maiale e derivati, e alcol. Assicurati che ogni analisi menu evidenzi la presenza di questi elementi vietati.
12. Priorità assoluta: Sicurezza medica/Etica Alimentare > Sapore > Creatività.
`;
};

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const t = i18n[diagnostics.language as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Condizioni: ${diagnostics.medicalConditions}. 
  Allergie: ${diagnostics.allergies}. 
  Ingredienti forniti: ${diagnostics.ingredients}.
  Specifiche: ${diagnostics.additionalSpecs}.

  ATTENZIONE: Se gli ingredienti sono incompatibili o pericolosi, evidenzialo chiaramente in colonna e proponi alternative nel campo 'medicalAnalysis'.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING, description: `${safetyHeader} seguito da lista verticale con '-' per ogni punto.` },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING, description: "Validazione scientifica e analisi sapori (usa elenchi verticali se necessario)." },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING },
              glycemicIndex: { type: Type.STRING },
              glycemicLoad: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + `\nStai assistendo l'utente per la ricetta "${recipe.title}". 
      TUTTE LE LISTE DEVONO ESSERE IN COLONNA (una riga per elemento).
      Se l'utente propone nuovi ingredienti, valuta compatibilità di sapore e sicurezza medica/dietetica (${diagnostics.medicalConditions}).
      In caso di sostituzioni usa questo formato:
      - ORIGINALE: [Nome]
      - SOSTITUTO: [Nome]
      - MOTIVO: [Dettaglio]`,
    },
  });
};

export const analyzeHealthOrMenu = async (
  query: string, 
  diagnostics: UserDiagnostics, 
  imageBase64?: string
): Promise<string> => {
  const parts: any[] = [{ text: query }];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64.split(',')[1],
        mimeType: "image/jpeg"
      }
    });
  }

  const prompt = `Analisi basata su:\nQuery: ${query}\nCondizioni mediche: ${diagnostics.medicalConditions}\nAllergie: ${diagnostics.allergies}\nObiettivi/Regimi: ${diagnostics.additionalSpecs}`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: [...parts, { text: prompt }] },
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + "\nSei nel centro diagnostico. Se viene fornita un'immagine di un menu, scarta categoricamente piatti che violano le restrizioni dietetiche fornite (Vegano, Musulmano, Pescateriano, ecc.). Identifica i piatti sicuri. Se un piatto contiene ingredienti vietati (es. maiale per Musulmano, carne per Vegano), segnalalo esplicitamente e sconsiglialo.",
    }
  });

  return response.text || "ERRORE ANALISI";
};

