const CameraScanner: React.FC<{ onCapture: (base64: string) => void, onClose: () => void, t: Translations }> = ({ onCapture, onClose, t }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError(t.cameraAccessDenied);
      }
    }
    startCamera();

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
        tracks.forEach(track => track.stop());
      }
    };
  }, [t]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(base64);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-4">
      <div className="relative w-full max-w-lg aspect-[3/4] border-2 border-white/20 overflow-hidden bg-black/50">
        {error ? (
          <div className="absolute inset-0 flex items-center justify-center text-center p-6 text-[10px] uppercase tracking-widest text-red-500 font-bold">
            {error}
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            {/* Cyber Overlay */}
            <div className="absolute inset-0 pointer-events-none">
              <div className="absolute top-4 left-4 w-8 h-8 border-l-2 border-t-2 border-white/40"></div>
              <div className="absolute top-4 right-4 w-8 h-8 border-r-2 border-t-2 border-white/40"></div>
              <div className="absolute bottom-4 left-4 w-8 h-8 border-l-2 border-b-2 border-white/40"></div>
              <div className="absolute bottom-4 right-4 w-8 h-8 border-r-2 border-b-2 border-white/40"></div>
              <div className="absolute inset-0 flex items-center justify-center opacity-20">
                <div className="w-48 h-48 border border-dashed border-white rounded-full animate-pulse"></div>
              </div>
              <div className="absolute top-1/2 left-0 w-full h-0.5 bg-green-500/30 animate-[scan_2s_linear_infinite]"></div>
              <div className="absolute top-6 left-1/2 -translate-x-1/2 text-[8px] font-bold tracking-[0.3em] uppercase opacity-60">
                {t.scanningTarget}
              </div>
            </div>
          </>
        )}
      </div>

      <div className="mt-8 flex gap-6">
        <button 
          onClick={onClose}
          className="px-6 py-2 border border-white/20 text-[10px] uppercase font-bold tracking-widest hover:bg-white/10"
          style={{ color: 'var(--text-color)' }}
        >
          {t.cancelBtn}
        </button>
        {!error && (
          <button 
            onClick={capture}
            className="px-8 py-2 bg-white text-black text-[10px] font-bold uppercase tracking-widest hover:scale-105 active:scale-95 transition-all"
          >
            {t.captureData}
          </button>
        )}
      </div>

      <canvas ref={canvasRef} style={{ display: 'none' }} />

      <style>{`
        @keyframes scan {
          0% { transform: translateY(-150px); }
          100% { transform: translateY(150px); }
        }
      `}</style>
    </div>
  );
};

const MenuOverlay: React.FC<{ image: string, detections: DetectedItem[] }> = ({ image, detections }) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'SAFE': return '#22c55e'; // Green
      case 'WARNING': return '#f59e0b'; // Yellow
      case 'FORBIDDEN': return '#ef4444'; // Red
      default: return '#ffffff';
    }
  };

  return (
    <div className="relative w-full border border-white/10 mb-6 bg-black">
      <div className="relative inline-block w-full">
        <img src={image} alt="Menu" className="w-full h-auto block" />
        <svg 
          viewBox="0 0 1000 1000" 
          className="absolute inset-0 w-full h-full pointer-events-auto"
          preserveAspectRatio="none"
        >
          {detections.map((item, idx) => {
            const [ymin, xmin, ymax, xmax] = item.box_2d;
            const color = getStatusColor(item.status);
            return (
              <g 
                key={idx}
                onMouseEnter={() => setHoveredIdx(idx)}
                onMouseLeave={() => setHoveredIdx(null)}
                className="cursor-help"
              >
                <rect
                  x={xmin}
                  y={ymin}
                  width={xmax - xmin}
                  height={ymax - ymin}
                  fill={color}
                  fillOpacity={hoveredIdx === idx ? 0.3 : 0.1}
                  stroke={color}
                  strokeWidth="4"
                  className="transition-all duration-200"
                />
                {hoveredIdx === idx && (
                   <rect
                    x={xmin}
                    y={ymin - 40 < 0 ? ymin : ymin - 40}
                    width="200"
                    height="30"
                    fill="black"
                    stroke={color}
                    strokeWidth="1"
                   />
                )}
                {hoveredIdx === idx && (
                  <text
                    x={xmin + 5}
                    y={ymin - 20 < 20 ? ymin + 20 : ymin - 20}
                    fill="white"
                    fontSize="16"
                    fontWeight="bold"
                    className="pointer-events-none"
                  >
                    {item.name}
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>

      {/* Legenda ed Espansione Dettagli */}
      <div className="p-4 border-t border-white/10 bg-black/40 text-[10px] space-y-3 font-mono">
        <div className="flex gap-4 border-b border-white/5 pb-2 mb-2">
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-green-500"></div> SAFE</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-yellow-500"></div> WARNING</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-red-500"></div> FORBIDDEN</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {detections.map((item, idx) => (
            <div 
              key={idx} 
              className={`p-2 border transition-all ${hoveredIdx === idx ? 'bg-white/5 border-white/40 translate-x-1' : 'border-transparent'}`}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
            >
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5" style={{ backgroundColor: getStatusColor(item.status) }}></div>
                <span className="font-bold uppercase tracking-tighter">{item.name}</span>
              </div>
              <div className="opacity-60 text-[9px] lowercase italic leading-tight">
                // {item.reason}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const QuestionTerminal: React.FC<Props> = ({ t, diagnostics }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListeningMain, setIsListeningMain] = useState(false);
  const [activeMicField, setActiveMicField] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [localCtx, setLocalCtx] = useState({
    conditions: diagnostics.medicalConditions || '',
    allergies: diagnostics.allergies || '',
    goal: '',
    otherGoal: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const startVoiceInputForField = useCallback((field: 'conditions' | 'allergies' | 'otherGoal') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(field);
    recognition.onend = () => setActiveMicField(null);
    recognition.onerror = () => setActiveMicField(null);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setLocalCtx(prev => ({ ...prev, [field]: prev[field as keyof typeof prev] ? `${prev[field as keyof typeof prev]} ${transcript}` : transcript }));
    };
    recognition.start();
  }, [selectedLang]);

  const handleCancelProcessing = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsProcessing(false);
  };

  const handleSend = async (image?: string) => {
    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);
    setIsCameraOpen(false);

    abortControllerRef.current = new AbortController();

    const finalGoal = localCtx.goal === 'ALTRO' ? localCtx.otherGoal : localCtx.goal;
    const effectiveDiagnostics: UserDiagnostics = {
      ...diagnostics,
      medicalConditions: localCtx.conditions,
      allergies: localCtx.allergies,
      additionalSpecs: finalGoal ? `OBIETTIVO/REGIME: ${finalGoal}. ${diagnostics.additionalSpecs}` : diagnostics.additionalSpecs
    };

    try {
      const result = await analyzeHealthOrMenu(query, effectiveDiagnostics, image);
      setMessages(prev => [...prev, { role: 'model', text: result.text, detections: result.detections, image: image }]);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Query aborted by user');
      } else {
        setMessages(prev => [...prev, { role: 'model', text: t.criticalErrorChat }]);
      }
    } finally {
      setIsProcessing(false);
      abortControllerRef.current = null;
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const MicIcon = ({ isActive }: { isActive: boolean }) => (
    <svg className={`w-3 h-3 ${isActive ? 'recording-pulse' : 'opacity-40 hover:opacity-100 transition-opacity cursor-pointer'}`} fill="currentColor" viewBox="0 0 24 24">
      <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
    </svg>
  );

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {isCameraOpen && <CameraScanner t={t} onClose={() => setIsCameraOpen(false)} onCapture={(b64) => handleSend(b64)} />}

      {/* Loading Overlay replicating Home experience */}
      {isProcessing && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500 bg-black/40">
          <button 
            onClick={handleCancelProcessing}
            className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
            style={{ color: 'var(--text-color)' }}
          >
