import { GoogleGenAI, Type, Chat, GenerateContentResponse } from "@google/genai";
import { UserDiagnostics, Recipe, DetectedItem } from "../types";
import { i18n } from "../translations";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (lang: string) => {
  const t = i18n[lang as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  return `Sei Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. FORMATO ELENCHI: Ogni volta che presenti un elenco (ingredienti, passaggi, avvisi), scrivi ogni elemento su una NUOVA RIGA.
4. ANALISI CLINICA (IMPORTANTE): Il campo 'medicalAnalysis' deve iniziare con '${safetyHeader}' seguito da un elenco puntato (usa '-') dove ogni punto occupa una nuova riga.
5. SPAZIATURA: Usa una riga vuota tra i blocchi di testo.
6. Lingua: ${lang}. Rispondi SEMPRE nella lingua dell'utente.

LOGICA DI VALUTAZIONE (CRITICA):
7. SICUREZZA MEDICA E DIETE SPECIFICHE: Valuta rigorosamente condizioni mediche, allergie e REGIMI ALIMENTARI (Vegano, Pescateriano, Musulmano/Halal).
8. REGIMI SPECIALI:
    - VEGANO: Scarta rigorosamente ogni derivato animale.
    - PESCATARIANO: Scarta carne ma accetta pesce.
    - MUSULMANO: Scarta rigorosamente maiale e alcol.
9. ANALISI VISIVA MENU: Se ricevi un'immagine di un menu, devi identificare ogni piatto e fornire le coordinate della sua posizione nell'immagine (box_2d) in formato [ymin, xmin, ymax, xmax] (range 0-1000).
10. CLASSIFICAZIONE COLORI:
    - SAFE (Verde): Piatti sicuri.
    - WARNING (Giallo): Piatti che richiedono attenzione o piccole modifiche.
    - FORBIDDEN (Rosso): Piatti pericolosi o che violano il regime alimentare.
11. Priorità assoluta: Sicurezza medica/Etica Alimentare > Sapore > Creatività.
12. TEMPO DI COTTURA: Stima il tempo totale necessario (es. "45 minuti", "1 ora") basandoti sulla complessità della ricetta.
`;
};

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const t = i18n[diagnostics.language as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Condizioni: ${diagnostics.medicalConditions}. 
  Allergie: ${diagnostics.allergies}. 
  Ingredienti forniti: ${diagnostics.ingredients}.
  Specifiche: ${diagnostics.additionalSpecs}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          cookingTime: { type: Type.STRING, description: "Estimated total cooking time" },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros", "cookingTime"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + `\nStai assistendo l'utente per la ricetta "${recipe.title}".`,
    },
  });
};

export const analyzeHealthOrMenu = async (
  query: string, 
  diagnostics: UserDiagnostics, 
  imageBase64?: string
): Promise<{ text: string, detections?: DetectedItem[] }> => {
  const parts: any[] = [{ text: query }];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64.split(',')[1],
        mimeType: "image/jpeg"
      }
    });
  }

  const prompt = `Analisi basata su:\nQuery: ${query}\nCondizioni mediche: ${diagnostics.medicalConditions}\nAllergie: ${diagnostics.allergies}\nObiettivi/Regimi: ${diagnostics.additionalSpecs}`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: [...parts, { text: prompt }] },
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: { type: Type.STRING, description: "Analisi testuale dettagliata." },
          detections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                status: { type: Type.STRING, enum: ['SAFE', 'WARNING', 'FORBIDDEN'] },
                box_2d: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                reason: { type: Type.STRING }
              },
              required: ["name", "status", "box_2d", "reason"]
            }
          }
        },
        required: ["text"]
      }
    }
  });

  const parsed = JSON.parse(response.text);
  return {
    text: parsed.text,
    detections: parsed.detections
  };
};

import React, { useState, useRef, useEffect } from 'react';
import { Recipe, Translations } from '../types';
import { jsPDF } from 'jspdf';

interface Props {
  recipe: Recipe;
  t: Translations;
}

const RecipeDisplay: React.FC<Props> = ({ recipe, t }) => {
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);
  const [isExportOpen, setIsExportOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsExportOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getFullText = () => {
    return `
# ${recipe.title}
---
${t.cookingTimeLabel.toUpperCase()}: ${recipe.cookingTime}

${t.clinicalAnalysis.toUpperCase()}
${recipe.medicalAnalysis}

${t.hardware.toUpperCase()}
${recipe.ingredients.map(ing => `- ${ing.name}: ${ing.amount} (${ing.function})`).join('\n')}

${t.protocol.toUpperCase()}
${recipe.procedure.map((step, idx) => `${idx + 1}. ${step}`).join('\n')}

${t.telemetry.toUpperCase()}
- Calories: ${recipe.macros.calories}
- Protein: ${recipe.macros.protein}
- Carbs: ${recipe.macros.carbs}
- Fats: ${recipe.macros.fats}
- Fiber: ${recipe.macros.fiber}

${t.scienceLog.toUpperCase()}
${recipe.scienceCheck}
    `.trim();
  };

  const handleShare = async () => {
    const text = getFullText();
    if (navigator.share) {
      try {
        await navigator.share({
          title: recipe.title,
          text: text,
        });
      } catch (err) {
        copyToClipboard();
      }
    } else {
      copyToClipboard();
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getFullText()).then(() => {
      setShowCopyFeedback(true);
      setTimeout(() => setShowCopyFeedback(false), 2000);
      setIsExportOpen(false);
    });
  };

  const downloadTxt = () => {
    const element = document.createElement("a");
    const file = new Blob([getFullText()], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `${recipe.title.replace(/\s+/g, '_')}_Omoikane.txt`;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
    setIsExportOpen(false);
  };

  const generatePdf = () => {
    const doc = new jsPDF();
    const margin = 15;
    const pageWidth = doc.internal.pageSize.getWidth();
    const maxLineWidth = pageWidth - margin * 2;

    let cursorY = margin;

    // Title
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    doc.text(recipe.title.toUpperCase(), margin, cursorY);
    cursorY += 10;

    // Cooking Time
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text(`${t.cookingTimeLabel.toUpperCase()}: ${recipe.cookingTime}`, margin, cursorY);
    cursorY += 10;

    // Clinical Analysis
    doc.setFont("helvetica", "bold");
    doc.text(t.clinicalAnalysis.toUpperCase() + ":", margin, cursorY);
    cursorY += 6;
    doc.setFont("helvetica", "normal");
    const medicalLines = doc.splitTextToSize(recipe.medicalAnalysis, maxLineWidth);
    doc.text(medicalLines, margin, cursorY);
    cursorY += medicalLines.length * 5 + 8;

    // Ingredients
    doc.setFont("helvetica", "bold");
    doc.text(t.hardware.toUpperCase() + ":", margin, cursorY);
    cursorY += 6;
    doc.setFont("helvetica", "normal");
    recipe.ingredients.forEach(ing => {
      const line = `- ${ing.name}: ${ing.amount} (${ing.function})`;
      const ingLines = doc.splitTextToSize(line, maxLineWidth);
      doc.text(ingLines, margin, cursorY);
      cursorY += ingLines.length * 5;
    });
    cursorY += 8;

    // Procedure
    if (cursorY > 250) { doc.addPage(); cursorY = margin; }
    doc.setFont("helvetica", "bold");
    doc.text(t.protocol.toUpperCase() + ":", margin, cursorY);
    cursorY += 6;
    doc.setFont("helvetica", "normal");
    recipe.procedure.forEach((step, idx) => {
      const line = `${idx + 1}. ${step}`;
      const stepLines = doc.splitTextToSize(line, maxLineWidth);
      if (cursorY + stepLines.length * 5 > 280) { doc.addPage(); cursorY = margin; }
      doc.text(stepLines, margin, cursorY);
      cursorY += stepLines.length * 5 + 2;
    });
    cursorY += 8;

    // Telemetry
    if (cursorY > 250) { doc.addPage(); cursorY = margin; }
    doc.setFont("helvetica", "bold");
    doc.text(t.telemetry.toUpperCase() + ":", margin, cursorY);
    cursorY += 6;
    doc.setFont("helvetica", "normal");
    const macros = [
      `Calories: ${recipe.macros.calories}`,
      `Protein: ${recipe.macros.protein}`,
      `Carbs: ${recipe.macros.carbs}`,
      `Fats: ${recipe.macros.fats}`,
      `Fiber: ${recipe.macros.fiber}`
    ];
    macros.forEach(m => {
      doc.text(m, margin, cursorY);
      cursorY += 5;
    });
    cursorY += 8;

    // Science Log
    if (cursorY > 250) { doc.addPage(); cursorY = margin; }
    doc.setFont("helvetica", "bold");
    doc.text(t.scienceLog.toUpperCase() + ":", margin, cursorY);
    cursorY += 6;
    doc.setFont("helvetica", "italic");
    const scienceLines = doc.splitTextToSize(recipe.scienceCheck, maxLineWidth);
    doc.text(scienceLines, margin, cursorY);

    doc.save(`${recipe.title.replace(/\s+/g, '_')}_Omoikane.pdf`);
    setIsExportOpen(false);
  };

  return (
    <div className="space-y-12 animate-in fade-in duration-700 printable-recipe">
