export type AppLanguage = 'Chinese' | 'English' | 'Español' | 'Français' | 'Italiano' | 'Japanese';
export type AppTheme = 'dark' | 'light';
export type AppView = 'synthesis' | 'questions';

export interface UserDiagnostics {
  medicalConditions: string;
  allergies: string;
  preferences: string;
  ingredients: string;
  targetDish: string;
  additionalSpecs: string;
  language: AppLanguage;
}

export interface MacroNutrients {
  calories: string;
  protein: string;
  carbs: string;
  fats: string;
  fiber: string;
  glycemicIndex?: string;
  glycemicLoad?: string;
}

export interface Recipe {
  title: string;
  medicalAnalysis: string;
  ingredients: { name: string; amount: string; function: string }[];
  procedure: string[];
  scienceCheck: string;
  macros: MacroNutrients;
  cookingTime: string;
}

export interface DetectedItem {
  name: string;
  status: 'SAFE' | 'WARNING' | 'FORBIDDEN';
  box_2d: [number, number, number, number]; // [ymin, xmin, ymax, xmax]
  reason: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
