const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (lang: string) => {
  const t = i18n[lang as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  return `Sei Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. FORMATO ELENCHI: Ogni volta che presenti un elenco (ingredienti, passaggi, avvisi), scrivi ogni elemento su una NUOVA RIGA.
4. ANALISI CLINICA (IMPORTANTE): Il campo 'medicalAnalysis' deve iniziare con '${safetyHeader}' seguito da un elenco puntato (usa '-') dove ogni punto occupa una nuova riga.
5. SPAZIATURA: Usa una riga vuota tra i blocchi di testo.
6. Lingua: ${lang}. Rispondi SEMPRE nella lingua dell'utente.

LOGICA DI VALUTAZIONE (CRITICA):
7. SICUREZZA MEDICA E DIETE SPECIFICHE: Valuta rigorosamente condizioni mediche, allergie e REGIMI ALIMENTARI (Vegano, Pescateriano, Musulmano/Halal).
8. REGIMI SPECIALI:
    - VEGANO: Scarta rigorosamente ogni derivato animale.
    - PESCATARIANO: Scarta carne ma accetta pesce.
    - MUSULMANO: Scarta rigorosamente maiale e alcol.
9. ANALISI VISIVA MENU E PRODOTTI: Se ricevi un'immagine, identifica piatti o prodotti commerciali. Se sono prodotti confezionati, usa Google Search per trovare i valori nutrizionali precisi.
10. CLASSIFICAZIONE COLORI:
    - SAFE (Verde): Piatti sicuri.
    - WARNING (Giallo): Piatti che richiedono attenzione o piccole modifiche.
    - FORBIDDEN (Rosso): Piatti pericolosi o che violano il regime alimentare.
11. Priorità assoluta: Sicurezza medica/Etica Alimentare > Sapore > Creatività.
12. TEMPO DI COTTURA: Stima il tempo totale necessario (es. "45 minuti", "1 ora") basandoti sulla complessità della ricetta.
`;
};

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const t = i18n[diagnostics.language as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Condizioni: ${diagnostics.medicalConditions}. 
  Allergie: ${diagnostics.allergies}. 
  Ingredienti forniti: ${diagnostics.ingredients}.
  Specifiche: ${diagnostics.additionalSpecs}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          cookingTime: { type: Type.STRING, description: "Estimated total cooking time" },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros", "cookingTime"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + `\nStai assistendo l'utente per la ricetta "${recipe.title}".`,
    },
  });
};

export const analyzeHealthOrMenu = async (
  query: string, 
  diagnostics: UserDiagnostics, 
  imageBase64?: string
): Promise<{ text: string, detections?: DetectedItem[], sources?: { title: string, uri: string }[] }> => {
  const parts: any[] = [{ text: query }];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64.split(',')[1],
        mimeType: "image/jpeg"
      }
    });
  }

  const prompt = `Analisi basata su:\nQuery: ${query}\nCondizioni mediche: ${diagnostics.medicalConditions}\nAllergie: ${diagnostics.allergies}\nObiettivi/Regimi: ${diagnostics.additionalSpecs}\n\nSe l'immagine mostra un prodotto commerciale, cerca su Google i suoi valori nutrizionali reali.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: [...parts, { text: prompt }] },
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: { type: Type.STRING, description: "Analisi testuale dettagliata." },
          detections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                status: { type: Type.STRING, enum: ['SAFE', 'WARNING', 'FORBIDDEN'] },
                box_2d: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                reason: { type: Type.STRING }
              },
              required: ["name", "status", "box_2d", "reason"]
            }
          }
        },
        required: ["text"]
      }
    }
  });

  const parsed = JSON.parse(response.text);

  // Estrai le sorgenti dal grounding metadata
  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.filter(chunk => chunk.web)
    ?.map(chunk => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })) || [];

  return {
    text: parsed.text,
    detections: parsed.detections,
    sources: sources.length > 0 ? sources : undefined
  };
};

