const QuestionTerminal: React.FC<Props> = ({ t, diagnostics }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeMicField, setActiveMicField] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [localCtx, setLocalCtx] = useState({
    conditions: diagnostics.medicalConditions || '',
    allergies: diagnostics.allergies || '',
    goal: '',
    otherGoal: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const handleInputFocus = () => {
    // Ensure the input is visible when keyboard opens on mobile
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const startVoiceInputForField = useCallback((field: 'conditions' | 'allergies' | 'otherGoal') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(field);
    recognition.onend = () => setActiveMicField(null);
    recognition.onerror = () => setActiveMicField(null);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setLocalCtx(prev => ({ ...prev, [field]: prev[field as keyof typeof prev] ? `${prev[field as keyof typeof prev]} ${transcript}` : transcript }));
    };
    recognition.start();
  }, [selectedLang]);

  const handleCancelProcessing = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsProcessing(false);
  };

  const handleSend = async (image?: string) => {
    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);
    setIsCameraOpen(false);

    abortControllerRef.current = new AbortController();

    const finalGoal = localCtx.goal === 'ALTRO' ? localCtx.otherGoal : localCtx.goal;
    const effectiveDiagnostics: UserDiagnostics = {
      ...diagnostics,
      medicalConditions: localCtx.conditions,
      allergies: localCtx.allergies,
      additionalSpecs: finalGoal ? `OBIETTIVO/REGIME: ${finalGoal}. ${diagnostics.additionalSpecs}` : diagnostics.additionalSpecs
    };

    try {
      const result = await analyzeHealthOrMenu(query, effectiveDiagnostics, image);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: result.text, 
        detections: result.detections, 
        image: image,
        sources: result.sources 
      }]);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Query aborted by user');
      } else {
        setMessages(prev => [...prev, { role: 'model', text: t.criticalErrorChat }]);
      }
    } finally {
      setIsProcessing(false);
      abortControllerRef.current = null;
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const MicIcon = ({ isActive }: { isActive: boolean }) => (
    <svg className={`w-3 h-3 ${isActive ? 'recording-pulse' : 'opacity-40 hover:opacity-100 transition-opacity cursor-pointer'}`} fill="currentColor" viewBox="0 0 24 24">
      <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
    </svg>
  );

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {isCameraOpen && <CameraScanner t={t} onClose={() => setIsCameraOpen(false)} onCapture={(b64) => handleSend(b64)} />}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500 bg-black/40">
          <button 
            onClick={handleCancelProcessing}
            className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
            style={{ color: 'var(--text-color)' }}
          >
            <div className="w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all hover:scale-110 active:scale-90 bg-black/10 backdrop-blur-md" style={{ borderColor: 'var(--border-color)' }}>
              <span className="text-2xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
            </div>
            <span className="text-[10px] font-black tracking-[0.2em] uppercase opacity-70 group-hover:opacity-100 transition-opacity">
              {t.cancelBtn}
            </span>
          </button>

          <div className="flex flex-col items-center space-y-12">
            <div className="relative w-40 h-40 flex items-center justify-center">
              <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-3 border-t-2 border-b-2 rounded-full animate-[spin_4s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-6 border-l-2 border-r-2 rounded-full animate-[spin_2s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="w-8 h-8 rounded-full animate-pulse shadow-[0_0_20px_rgba(255,255,255,0.4)]" style={{ backgroundColor: 'var(--text-color)' }}></div>
              <div className="absolute w-full h-0.5 animate-[loading-scan_2.5s_ease-in-out_infinite] opacity-20" style={{ backgroundColor: 'var(--text-color)' }}></div>
            </div>

            <div className="text-center space-y-6 max-w-sm">
              <div className="space-y-2">
                <p className="text-[14px] font-black tracking-[1em] uppercase animate-pulse pr-[-1em]" style={{ color: 'var(--text-color)' }}>
                  {t.loading}
                </p>
                <div className="h-1 w-full bg-white/10 relative overflow-hidden rounded-full">
                  <div className="absolute inset-0 bg-current animate-[loading-progress_3.5s_ease-in-out_infinite]"></div>
                </div>
              </div>
              <p className="text-[10px] opacity-70 uppercase tracking-[0.25em] font-mono leading-relaxed bg-black/5 p-2 rounded backdrop-blur-sm">
                {t.analysisClinicalParams}<br/>
                {t.syncDiagnosticMatrix}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="glow-border p-4 bg-black/20" style={{ borderColor: 'var(--border-color)' }}>
          <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
            <span className="w-1 h-1 bg-red-500 rounded-full animate-pulse"></span>
            {t.activeClinicalProfile}
          </div>
          <div className="space-y-3">
            <div className="relative group">
              <input type="text" placeholder={t.medicalConditionsPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.conditions} onChange={(e) => setLocalCtx({...localCtx, conditions: e.target.value})} />
              <button type="button" onClick={() => startVoiceInputForField('conditions')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'conditions'} /></button>
            </div>
            <div className="relative group">
              <input type="text" placeholder={t.allergiesPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.allergies} onChange={(e) => setLocalCtx({...localCtx, allergies: e.target.value})} />
              <button type="button" onClick={() => startVoiceInputForField('allergies')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'allergies'} /></button>
            </div>
          </div>
        </div>
        <div className="glow-border p-4 bg-black/20 flex flex-col justify-between" style={{ borderColor: 'var(--border-color)' }}>
          <div>
            <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
              <span className="w-1 h-1 bg-blue-500 rounded-full"></span>
              {t.goalsAndRegimes}
            </div>
            <select className="w-full bg-transparent border border-white/10 text-[10px] p-2 outline-none hover:bg-white/5 transition-all uppercase font-mono cursor-pointer" style={{ color: 'var(--text-color)' }} value={localCtx.goal} onChange={(e) => setLocalCtx({...localCtx, goal: e.target.value})}>
              <option value="" className="bg-black">{t.selectGoal}</option>
              <option value="PERDITA_PESO" className="bg-black">{t.goalWeightLoss}</option>
              <option value="MASSA_MUSCOLARE" className="bg-black">{t.goalMuscleMass}</option>
              <option value="CONTROLLO_GLICEMICO" className="bg-black">{t.goalGlycemicControl}</option>
              <option value="VEGANO" className="bg-black">{t.goalVegan}</option>
              <option value="PESCATARIANO" className="bg-black">{t.goalPescatarian}</option>
              <option value="MUSULMANO" className="bg-black">{t.goalMuslim}</option>
              <option value="ANTI_INFIAMMATORIO" className="bg-black">{t.goalAntiInflammatory}</option>
              <option value="ALTRO" className="bg-black">{t.goalOther}</option>
            </select>
          </div>
        </div>
      </div>

      <div className="glow-border flex flex-col min-h-[400px] h-[60vh] rounded-none overflow-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
        <div className="border-b p-4 flex justify-between items-center" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <h2 className="header-font text-xs font-bold tracking-[0.2em] uppercase" style={{ color: 'var(--text-color)' }}>{t.healthCenter}</h2>
          <div className="flex gap-2">
            <button onClick={() => setIsCameraOpen(true)} className="px-3 py-1 border text-[8px] font-bold uppercase hover:bg-white/10 flex items-center gap-2" style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}>
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              {t.liveScan}
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="px-3 py-1 border text-[8px] font-bold uppercase hover:bg-white/10 flex items-center gap-2" style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}>
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              {t.uploadMenu}
            </button>
          </div>
          <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleFileUpload} />
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 font-mono custom-scrollbar">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 border ${msg.role === 'user' ? 'bg-white text-black' : ''}`} style={{ borderColor: 'var(--border-color)' }}>
                <div className="text-[7px] uppercase font-bold mb-2 opacity-50 border-b pb-1">
                  {msg.role === 'user' ? t.unitPilot : t.chefOmoikaneLabel}
                </div>
                {msg.image && msg.detections ? (
                   <MenuOverlay image={msg.image} detections={msg.detections} />
                ) : msg.image && (
                   <img src={msg.image} alt="User Upload" className="mb-4 max-w-full border p-1" style={{ borderColor: 'var(--border-color)' }} />
                )}
                <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.text}</div>

                {/* Visualizzazione Sorgenti Web */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10">
                    <div className="text-[8px] font-bold uppercase tracking-widest opacity-50 mb-2">{t.webSources}</div>
                    <div className="flex flex-col gap-2">
                      {msg.sources.map((source, sIdx) => (
                        <a 
                          key={sIdx} 
                          href={source.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-[9px] text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-1 group"
                        >
                          <svg className="w-2.5 h-2.5 opacity-40 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          <span className="truncate max-w-xs">{source.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={scrollRef} />
        </div>

        <form 
          ref={formRef}
          onSubmit={(e) => { e.preventDefault(); handleSend(); }} 
          className="p-4 border-t flex gap-4" 
          style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}
        >
          <div className="flex-1 relative flex items-center">
            <span className="mr-3 opacity-30">{'>'}</span>
            <input 
              ref={inputRef}
              type="text" 
              className="flex-1 bg-transparent outline-none text-sm font-mono" 
              style={{ color: 'var(--text-color)' }} 
              placeholder={t.chatPlaceholder} 
              value={input} 
              onFocus={handleInputFocus}
              onChange={(e) => setInput(e.target.value)} 
              disabled={isProcessing} 
            />
          </div>
          <button type="submit" disabled={isProcessing || !input.trim()} className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase disabled:opacity-20">{t.send}</button>
        </form>
      </div>
    </div>
  );
};

