import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Translations, UserDiagnostics, ChatMessage, DetectedItem } from '../types';
import { analyzeHealthOrMenu } from '../services/geminiService';
import { LANGUAGES } from '../App';

interface Props {
  t: Translations;
  diagnostics: UserDiagnostics;
}

const CameraScanner: React.FC<{ onCapture: (base64: string) => void, onClose: () => void, t: Translations }> = ({ onCapture, onClose, t }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError(t.cameraAccessDenied);
      }
    }
    startCamera();

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
        tracks.forEach(track => track.stop());
      }
    };
  }, [t]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(base64);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-4">
      <div className="relative w-full max-w-lg aspect-[3/4] border-2 border-white/20 overflow-hidden bg-black/50">
        {error ? (
          <div className="absolute inset-0 flex items-center justify-center text-center p-6 text-[10px] uppercase tracking-widest text-red-500 font-bold">
            {error}
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            {/* Cyber Overlay */}
            <div className="absolute inset-0 pointer-events-none">
              <div className="absolute top-4 left-4 w-8 h-8 border-l-2 border-t-2 border-white/40"></div>
              <div className="absolute top-4 right-4 w-8 h-8 border-r-2 border-t-2 border-white/40"></div>
              <div className="absolute bottom-4 left-4 w-8 h-8 border-l-2 border-b-2 border-white/40"></div>
              <div className="absolute bottom-4 right-4 w-8 h-8 border-r-2 border-b-2 border-white/40"></div>
              <div className="absolute inset-0 flex items-center justify-center opacity-20">
                <div className="w-48 h-48 border border-dashed border-white rounded-full animate-pulse"></div>
              </div>
              <div className="absolute top-1/2 left-0 w-full h-0.5 bg-green-500/30 animate-[scan_2s_linear_infinite]"></div>
              <div className="absolute top-6 left-1/2 -translate-x-1/2 text-[8px] font-bold tracking-[0.3em] uppercase opacity-60">
                {t.scanningTarget}
              </div>
            </div>
          </>
        )}
      </div>

      <div className="mt-8 flex gap-6">
        <button 
          onClick={onClose}
          className="px-6 py-2 border border-white/20 text-[10px] uppercase font-bold tracking-widest hover:bg-white/10"
          style={{ color: 'var(--text-color)' }}
        >
          {t.cancelBtn}
        </button>
        {!error && (
          <button 
            onClick={capture}
            className="px-8 py-2 bg-white text-black text-[10px] font-bold uppercase tracking-widest hover:scale-105 active:scale-95 transition-all"
          >
            {t.captureData}
          </button>
        )}
      </div>

      <canvas ref={canvasRef} style={{ display: 'none' }} />

      <style>{`
        @keyframes scan {
          0% { transform: translateY(-150px); }
          100% { transform: translateY(150px); }
        }
      `}</style>
    </div>
  );
};

const MenuOverlay: React.FC<{ image: string, detections: DetectedItem[] }> = ({ image, detections }) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'SAFE': return '#22c55e'; // Green
      case 'WARNING': return '#f59e0b'; // Yellow
      case 'FORBIDDEN': return '#ef4444'; // Red
      default: return '#ffffff';
    }
  };

  return (
    <div className="relative w-full border border-white/10 mb-6 bg-black">
      <div className="relative inline-block w-full">
        <img src={image} alt="Menu" className="w-full h-auto block" />
        <svg 
          viewBox="0 0 1000 1000" 
          className="absolute inset-0 w-full h-full pointer-events-auto"
          preserveAspectRatio="none"
        >
          {detections.map((item, idx) => {
            const [ymin, xmin, ymax, xmax] = item.box_2d;
            const color = getStatusColor(item.status);
            return (
              <g 
                key={idx}
                onMouseEnter={() => setHoveredIdx(idx)}
                onMouseLeave={() => setHoveredIdx(null)}
                className="cursor-help"
              >
                <rect
                  x={xmin}
                  y={ymin}
                  width={xmax - xmin}
                  height={ymax - ymin}
                  fill={color}
                  fillOpacity={hoveredIdx === idx ? 0.3 : 0.1}
                  stroke={color}
                  strokeWidth="4"
                  className="transition-all duration-200"
                />
                {hoveredIdx === idx && (
                   <rect
                    x={xmin}
                    y={ymin - 40 < 0 ? ymin : ymin - 40}
                    width="200"
                    height="30"
                    fill="black"
                    stroke={color}
                    strokeWidth="1"
                   />
                )}
                {hoveredIdx === idx && (
                  <text
                    x={xmin + 5}
                    y={ymin - 20 < 20 ? ymin + 20 : ymin - 20}
                    fill="white"
                    fontSize="16"
                    fontWeight="bold"
                    className="pointer-events-none"
                  >
                    {item.name}
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>

      {/* Legenda ed Espansione Dettagli */}
      <div className="p-4 border-t border-white/10 bg-black/40 text-[10px] space-y-3 font-mono">
        <div className="flex gap-4 border-b border-white/5 pb-2 mb-2">
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-green-500"></div> SAFE</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-yellow-500"></div> WARNING</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-red-500"></div> FORBIDDEN</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {detections.map((item, idx) => (
            <div 
              key={idx} 
              className={`p-2 border transition-all ${hoveredIdx === idx ? 'bg-white/5 border-white/40 translate-x-1' : 'border-transparent'}`}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
            >
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5" style={{ backgroundColor: getStatusColor(item.status) }}></div>
                <span className="font-bold uppercase tracking-tighter">{item.name}</span>
              </div>
              <div className="opacity-60 text-[9px] lowercase italic leading-tight">
                // {item.reason}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const QuestionTerminal: React.FC<Props> = ({ t, diagnostics }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeMicField, setActiveMicField] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [localCtx, setLocalCtx] = useState({
    conditions: diagnostics.medicalConditions || '',
    allergies: diagnostics.allergies || '',
    goal: '',
    otherGoal: ''
  });

  const isClinicallyValid = localCtx.conditions.trim().length > 0;

  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const handleInputFocus = () => {
    // Ensure the input is visible when keyboard opens on mobile
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const startVoiceInputForField = useCallback((field: 'conditions' | 'allergies' | 'otherGoal') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(field);
    recognition.onend = () => setActiveMicField(null);
    recognition.onerror = () => setActiveMicField(null);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setLocalCtx(prev => ({ ...prev, [field]: prev[field as keyof typeof prev] ? `${prev[field as keyof typeof prev]} ${transcript}` : transcript }));
    };
    recognition.start();
  }, [selectedLang]);

  const handleCancelProcessing = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsProcessing(false);
  };

  const handleSend = async (image?: string) => {
    if (!isClinicallyValid) return;

    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);
    setIsCameraOpen(false);

    abortControllerRef.current = new AbortController();

    const finalGoal = localCtx.goal === 'ALTRO' ? localCtx.otherGoal : localCtx.goal;
    const effectiveDiagnostics: UserDiagnostics = {
      ...diagnostics,
      medicalConditions: localCtx.conditions,
      allergies: localCtx.allergies,
      additionalSpecs: finalGoal ? `OBIETTIVO/REGIME: ${finalGoal}. ${diagnostics.additionalSpecs}` : diagnostics.additionalSpecs
    };

    try {
      const result = await analyzeHealthOrMenu(query, effectiveDiagnostics, image);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: result.text, 
        detections: result.detections, 
        image: image,
        sources: result.sources 
      }]);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Query aborted by user');
      } else {
        setMessages(prev => [...prev, { role: 'model', text: t.criticalErrorChat }]);
      }
    } finally {
      setIsProcessing(false);
      abortControllerRef.current = null;
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isClinicallyValid) return;
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const MicIcon = ({ isActive }: { isActive: boolean }) => (
    <svg className={`w-3 h-3 ${isActive ? 'recording-pulse' : 'opacity-40 hover:opacity-100 transition-opacity cursor-pointer'}`} fill="currentColor" viewBox="0 0 24 24">
      <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
    </svg>
  );

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {isCameraOpen && <CameraScanner t={t} onClose={() => setIsCameraOpen(false)} onCapture={(b64) => handleSend(b64)} />}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500 bg-black/40">
          <button 
            onClick={handleCancelProcessing}
            className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
            style={{ color: 'var(--text-color)' }}
          >
            <div className="w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all hover:scale-110 active:scale-90 bg-black/10 backdrop-blur-md" style={{ borderColor: 'var(--border-color)' }}>
              <span className="text-2xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
            </div>
            <span className="text-[10px] font-black tracking-[0.2em] uppercase opacity-70 group-hover:opacity-100 transition-opacity">
              {t.cancelBtn}
            </span>
          </button>

          <div className="flex flex-col items-center space-y-12">
            <div className="relative w-40 h-40 flex items-center justify-center">
              <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-3 border-t-2 border-b-2 rounded-full animate-[spin_4s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-6 border-l-2 border-r-2 rounded-full animate-[spin_2s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="w-8 h-8 rounded-full animate-pulse shadow-[0_0_20px_rgba(255,255,255,0.4)]" style={{ backgroundColor: 'var(--text-color)' }}></div>
              <div className="absolute w-full h-0.5 animate-[loading-scan_2.5s_ease-in-out_infinite] opacity-20" style={{ backgroundColor: 'var(--text-color)' }}></div>
            </div>

            <div className="text-center space-y-6 max-w-sm">
              <div className="space-y-2">
                <p className="text-[14px] font-black tracking-[1em] uppercase animate-pulse pr-[-1em]" style={{ color: 'var(--text-color)' }}>
                  {t.loading}
                </p>
                <div className="h-1 w-full bg-white/10 relative overflow-hidden rounded-full">
                  <div className="absolute inset-0 bg-current animate-[loading-progress_3.5s_ease-in-out_infinite]"></div>
                </div>
              </div>
              <p className="text-[10px] opacity-70 uppercase tracking-[0.25em] font-mono leading-relaxed bg-black/5 p-2 rounded backdrop-blur-sm">
                {t.analysisClinicalParams}<br/>
                {t.syncDiagnosticMatrix}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className={`glow-border p-4 bg-black/20 border-2 ${!isClinicallyValid ? 'border-red-500/50 animate-pulse' : ''}`} style={{ borderColor: isClinicallyValid ? 'var(--border-color)' : undefined }}>
          <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
            <span className={`w-1 h-1 rounded-full ${!isClinicallyValid ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></span>
            {t.activeClinicalProfile} {!isClinicallyValid && "[DATA_REQUIRED]"}
          </div>
          <div className="space-y-3">
            <div className="relative group">
              <input type="text" placeholder={t.medicalConditionsPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.conditions} onChange={(e) => setLocalCtx({...localCtx, conditions: e.target.value})} />
              <button type="button" onClick={() => startVoiceInputForField('conditions')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'conditions'} /></button>
            </div>
            <div className="relative group">
              <input type="text" placeholder={t.allergiesPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.allergies} onChange={(e) => setLocalCtx({...localCtx, allergies: e.target.value})} />
              <button type="button" onClick={() => startVoiceInputForField('allergies')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'allergies'} /></button>
            </div>
          </div>
        </div>
        <div className="glow-border p-4 bg-black/20 flex flex-col justify-between" style={{ borderColor: 'var(--border-color)' }}>
          <div>
            <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
              <span className="w-1 h-1 bg-blue-500 rounded-full"></span>
              {t.goalsAndRegimes}
            </div>
            <select className="w-full bg-transparent border border-white/10 text-[10px] p-2 outline-none hover:bg-white/5 transition-all uppercase font-mono cursor-pointer" style={{ color: 'var(--text-color)' }} value={localCtx.goal} onChange={(e) => setLocalCtx({...localCtx, goal: e.target.value})}>
              <option value="" className="bg-black">{t.selectGoal}</option>
              <option value="PERDITA_PESO" className="bg-black">{t.goalWeightLoss}</option>
              <option value="MASSA_MUSCOLARE" className="bg-black">{t.goalMuscleMass}</option>
              <option value="CONTROLLO_GLICEMICO" className="bg-black">{t.goalGlycemicControl}</option>
              <option value="VEGANO" className="bg-black">{t.goalVegan}</option>
              <option value="PESCATARIANO" className="bg-black">{t.goalPescatarian}</option>
              <option value="MUSULMANO" className="bg-black">{t.goalMuslim}</option>
              <option value="ANTI_INFIAMMATORIO" className="bg-black">{t.goalAntiInflammatory}</option>
              <option value="ALTRO" className="bg-black">{t.goalOther}</option>
            </select>
          </div>
        </div>
      </div>

      <div className="glow-border flex flex-col min-h-[400px] h-[60vh] rounded-none overflow-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
        <div className="border-b p-4 flex justify-between items-center flex-wrap gap-4" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <h2 className="header-font text-xs font-bold tracking-[0.2em] uppercase" style={{ color: 'var(--text-color)' }}>{t.healthCenter}</h2>

          {/* Highlighted Scan Buttons */}
          <div className={`flex gap-3 transition-all duration-300 ${!isClinicallyValid ? 'opacity-20 pointer-events-none grayscale' : 'opacity-100'}`}>
            <button 
              onClick={() => setIsCameraOpen(true)} 
              className="px-4 py-2 bg-white text-black text-[10px] font-black uppercase flex items-center gap-2 shadow-[0_0_15px_rgba(255,255,255,0.3)] hover:scale-105 transition-all active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                <circle cx="12" cy="13" r="3" strokeWidth={2.5} />
              </svg>
              {t.liveScan}
            </button>

            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="px-4 py-2 border-2 text-[10px] font-black uppercase flex items-center gap-2 hover:bg-white hover:text-black transition-all active:scale-95" 
              style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              {t.uploadMenu}
            </button>
          </div>
          <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleFileUpload} />
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 font-mono custom-scrollbar">
          {messages.length === 0 && !isClinicallyValid && (
             <div className="flex flex-col items-center justify-center h-full space-y-4 opacity-40">
                <svg className="w-12 h-12 text-red-500 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
                <p className="text-[10px] uppercase font-bold tracking-[0.2em] text-center max-w-xs">
                  [WARNING: SYSTEM_LOCKED]<br/>
                  PLEASE SPECIFY MEDICAL CONDITIONS ABOVE TO INITIALIZE DIAGNOSTIC SENSORS
                </p>
             </div>
          )}

          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 border ${msg.role === 'user' ? 'bg-white text-black' : ''}`} style={{ borderColor: 'var(--border-color)' }}>
                <div className="text-[7px] uppercase font-bold mb-2 opacity-50 border-b pb-1">
                  {msg.role === 'user' ? t.unitPilot : t.chefOmoikaneLabel}
                </div>
                {msg.image && msg.detections ? (
                   <MenuOverlay image={msg.image} detections={msg.detections} />
                ) : msg.image && (
                   <img src={msg.image} alt="User Upload" className="mb-4 max-w-full border p-1" style={{ borderColor: 'var(--border-color)' }} />
                )}
                <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.text}</div>

                {/* Visualizzazione Sorgenti Web */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10">
                    <div className="text-[8px] font-bold uppercase tracking-widest opacity-50 mb-2">{t.webSources}</div>
                    <div className="flex flex-col gap-2">
                      {msg.sources.map((source, sIdx) => (
                        <a 
                          key={sIdx} 
                          href={source.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-[9px] text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-1 group"
                        >
                          <svg className="w-2.5 h-2.5 opacity-40 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          <span className="truncate max-w-xs">{source.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={scrollRef} />
        </div>

        <form 
          ref={formRef}
          onSubmit={(e) => { e.preventDefault(); handleSend(); }} 
          className="p-4 border-t flex gap-4" 
          style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}
        >
          <div className="flex-1 relative flex items-center">
            <span className="mr-3 opacity-30">{'>'}</span>
            <input 
              ref={inputRef}
              type="text" 
              className={`flex-1 bg-transparent outline-none text-sm font-mono transition-opacity duration-300 ${!isClinicallyValid ? 'opacity-20' : 'opacity-100'}`} 
              style={{ color: 'var(--text-color)' }} 
              placeholder={isClinicallyValid ? t.chatPlaceholder : "[SYSTEM_LOCKED] ENTER CONDITIONS FIRST"} 
              value={input} 
              onFocus={handleInputFocus}
              onChange={(e) => setInput(e.target.value)} 
              disabled={isProcessing || !isClinicallyValid} 
            />
          </div>
          <button 
            type="submit" 
            disabled={isProcessing || !input.trim() || !isClinicallyValid} 
            className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase disabled:opacity-20 transition-all active:scale-95"
          >
            {t.send}
          </button>
        </form>
      </div>
    </div>
  );
};

export default QuestionTerminal;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import TerminalHeader from './components/TerminalHeader';
import DiagnosticTerminal from './components/DiagnosticTerminal';
import RecipeDisplay from './components/RecipeDisplay';
import RecipeChat from './components/RecipeChat';
import QuestionTerminal from './components/QuestionTerminal';
import HelpModal from './components/HelpModal';
import { UserDiagnostics, Recipe, AppLanguage, AppTheme, AppView } from './types';
import { i18n } from './translations';
import { generateRecipe, createRecipeChat } from './services/geminiService';
import { Chat } from '@google/genai';

export const LANGUAGES: { code: AppLanguage; label: string; flag: string; speechCode: string }[] = [
  { code: 'Chinese', label: '中文', flag: '🇨🇳', speechCode: 'zh-CN' },
  { code: 'English', label: 'ENGLISH', flag: '🇬🇧', speechCode: 'en-US' },
  { code: 'Español', label: 'ESPAÑOL', flag: '🇪🇸', speechCode: 'es-ES' },
  { code: 'Français', label: 'FRANÇAIS', flag: '🇫🇷', speechCode: 'fr-FR' },
  { code: 'Italiano', label: 'ITALIANO', flag: '🇮🇹', speechCode: 'it-IT' },
  { code: 'Japanese', label: '日本語', flag: '🇯🇵', speechCode: 'ja-JP' },
];

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('synthesis');
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [language, setLanguage] = useState<AppLanguage>('English');
  const [theme, setTheme] = useState<AppTheme>('dark');
  const [isHelpOpen, setIsHelpOpen] = useState(false);

  // Persist diagnostics for health queries
  const [diagnostics, setDiagnostics] = useState<UserDiagnostics>({
    medicalConditions: '',
    allergies: '',
    preferences: '',
    ingredients: '',
    targetDish: '',
    additionalSpecs: '',
    language: 'English'
  });

  const abortControllerRef = useRef<AbortController | null>(null);

  const t = useMemo(() => i18n[language], [language]);

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);

  const handleCancel = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setLoading(false);
    setError(null);
  };

  const updateDiagnostics = (updates: Partial<UserDiagnostics>) => {
    setDiagnostics(prev => ({ ...prev, ...updates }));
  };

  const handleDiagnosticSubmit = async (data: UserDiagnostics) => {
    setDiagnostics(data);
    setLoading(true);
    setError(null);
    setRecipe(null);
    setChatSession(null);

    abortControllerRef.current = new AbortController();

    try {
      const result = await generateRecipe(data);

      setRecipe(result);
      const session = createRecipeChat(result, data);
      setChatSession(session);

      setTimeout(() => {
        const el = document.getElementById('recipe-output');
        el?.scrollIntoView({ behavior: 'smooth' });
      }, 300);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Synthesis aborted by user');
      } else {
        setError(t.error);
      }
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <div className="min-h-screen pb-24 theme-transition font-mono selection:bg-white selection:text-black" style={{ color: 'var(--text-color)' }}>
      <TerminalHeader 
        t={t} 
        theme={theme} 
        onThemeToggle={toggleTheme} 
        language={language} 
        setLanguage={setLanguage}
        currentView={view}
        setView={setView}
        onHelpOpen={() => setIsHelpOpen(true)}
      />

      {isHelpOpen && <HelpModal t={t} onClose={() => setIsHelpOpen(false)} />}

      <main className="container mx-auto px-4 mt-12 space-y-16">
        <div className="max-w-5xl mx-auto">

          {view === 'synthesis' ? (
            <>
              <section className="mb-16">
                <DiagnosticTerminal 
                  onSumbit={handleDiagnosticSubmit} 
                  onUpdate={updateDiagnostics}
                  diagnostics={diagnostics}
                  isLoading={loading} 
                  language={language}
                  setLanguage={setLanguage}
                  t={t}
                />
              </section>

              {error && (
                <div className="p-4 border text-[10px] uppercase mb-12" style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}>
                  [SYSTEM_ERROR] {error}
                </div>
              )}

              {recipe && (
                <section id="recipe-output" className="pt-20 border-t" style={{ borderColor: 'var(--border-color)' }}>
                  <RecipeDisplay recipe={recipe} t={t} />
                  {chatSession && <RecipeChat chatSession={chatSession} t={t} />}
                  <div className="mt-16 flex justify-center">
                    <button 
                      onClick={() => {
                        setRecipe(null);
                        setChatSession(null);
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }}
                      className="px-8 py-2 border text-[9px] uppercase tracking-widest transition-all opacity-40 hover:opacity-100"
                      style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                    >
                      {t.newSynthesis}
                    </button>
                  </div>
                </section>
              )}
            </>
          ) : (
            <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <QuestionTerminal t={t} diagnostics={diagnostics} onUpdate={updateDiagnostics} />
            </section>
          )}

          {/* Loading Overlay */}
          {loading && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500" 
                 style={{ backgroundColor: theme === 'dark' ? 'rgba(0,0,0,0.4)' : 'rgba(255,255,255,0.4)' }}>

              <button 
                onClick={handleCancel}
                className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
                style={{ color: 'var(--text-color)' }}
                title="CANCEL_SYNTHESIS"
              >
                <div className="w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all hover:scale-110 active:scale-90 bg-black/10 backdrop-blur-md" style={{ borderColor: 'var(--border-color)' }}>
                  <span className="text-2xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
                </div>
                <span className="text-[10px] font-black tracking-[0.2em] uppercase opacity-70 group-hover:opacity-100 transition-opacity">
                  {t.cancelBtn}
                </span>
              </button>

              <div className="flex flex-col items-center space-y-12">
                <div className="relative w-40 h-40 flex items-center justify-center">
                  <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>
                  <div className="absolute inset-3 border-t-2 border-b-2 rounded-full animate-[spin_4s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>
                  <div className="absolute inset-6 border-l-2 border-r-2 rounded-full animate-[spin_2s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>
                  <div className="w-8 h-8 rounded-full animate-pulse shadow-[0_0_20px_rgba(255,255,255,0.4)]" style={{ backgroundColor: 'var(--text-color)' }}></div>
                  <div className="absolute w-full h-0.5 animate-[loading-scan_2.5s_ease-in-out_infinite] opacity-20" style={{ backgroundColor: 'var(--text-color)' }}></div>
                </div>

                <div className="text-center space-y-6 max-w-sm">
                  <div className="space-y-2">
                    <p className="text-[14px] font-black tracking-[1em] uppercase animate-pulse pr-[-1em]" style={{ color: 'var(--text-color)' }}>
                      {t.loading}
                    </p>
                    <div className="h-1 w-full bg-white/10 relative overflow-hidden rounded-full">
                      <div className="absolute inset-0 bg-current animate-[loading-progress_3.5s_ease-in-out_infinite]"></div>
                    </div>
                  </div>
                  <p className="text-[10px] opacity-70 uppercase tracking-[0.25em] font-mono leading-relaxed bg-black/5 p-2 rounded backdrop-blur-sm">
                    {t.syncDiagnosticMatrix}<br/>
                    {t.analysisClinicalParams}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 border-t py-2 px-6 flex justify-between items-center z-40 backdrop-blur-md" style={{ backgroundColor: 'var(--header-bg)', borderColor: 'var(--border-color)' }}>
        <div className="text-[7px] opacity-30 uppercase tracking-widest font-bold" style={{ color: 'var(--text-color)' }}>
          CHEF OMOIKANE // V5.0
        </div>
        <div className="flex gap-4">
          <span className="text-[7px] opacity-60 tracking-widest uppercase" style={{ color: 'var(--text-color)' }}>STABLE</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { UserDiagnostics, AppLanguage, Translations } from '../types';
import { LANGUAGES } from '../App';

interface Props {
  onSumbit: (data: UserDiagnostics) => void;
  onUpdate: (updates: Partial<UserDiagnostics>) => void;
  diagnostics: UserDiagnostics;
  isLoading: boolean;
  language: AppLanguage;
  setLanguage: (lang: AppLanguage) => void;
  t: Translations;
}

const DiagnosticTerminal: React.FC<Props> = ({ onSumbit, onUpdate, diagnostics, isLoading, language, t }) => {
  const [activeMic, setActiveMic] = useState<string | null>(null);
  const [formData, setFormData] = useState<UserDiagnostics>(diagnostics);

  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    setFormData(diagnostics);
  }, [diagnostics]);

  useEffect(() => {
    setFormData(prev => ({ ...prev, language }));
  }, [language]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSumbit(formData);
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const target = e.target;
    // Centra l'elemento nel viewport con un piccolo ritardo per permettere alla tastiera mobile di apparire
    setTimeout(() => {
      target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const selectedLang = LANGUAGES.find(l => l.code === language);

  const updateLocalAndGlobal = (field: keyof UserDiagnostics, value: string) => {
    const newData = { ...formData, [field]: value };
    setFormData(newData);
    // Notifica il genitore per la sincronizzazione se è un campo clinico
    if (field === 'medicalConditions' || field === 'allergies') {
      onUpdate({ [field]: value });
    }
  };

  const startVoiceInput = useCallback((field: keyof UserDiagnostics) => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("ERRORE SENSORI: Il browser non supporta il riconoscimento vocale.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setActiveMic(field as string);
    recognition.onend = () => setActiveMic(null);
    recognition.onerror = () => setActiveMic(null);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      const currentValue = formData[field] as string;
      const newValue = currentValue ? `${currentValue} ${transcript}` : transcript;
      updateLocalAndGlobal(field, newValue);
    };

    recognition.start();
  }, [selectedLang, formData]);

  const MicButton = ({ field }: { field: keyof UserDiagnostics }) => (
    <button
      type="button"
      onClick={() => startVoiceInput(field)}
      className={`absolute right-3 top-1/2 -translate-y-1/2 transition-all p-2 ${activeMic === field ? 'recording-pulse' : 'opacity-30 hover:opacity-100'}`}
      title="VOCAL_SENSOR_ACTIVATE"
    >
      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
        <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/>
        <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
      </svg>
    </button>
  );

  return (
    <div className="glow-border p-6 rounded-none relative overflow-visible" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
      <div className="absolute top-0 right-0">
        <div className="px-2 py-1 text-[8px] border-l border-b font-mono opacity-80" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}>
          LINK_ACTIVE // PORT_8080
        </div>
      </div>

      <h2 className="header-font text-lg mb-6 flex items-center gap-2 tracking-tighter" style={{ color: 'var(--text-color)' }}>
        <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: 'var(--text-color)' }}></span>
        {t.synthesisParams}
      </h2>

      <form ref={formRef} onSubmit={handleSubmit} className="space-y-6">
        <div className="border-b pb-6" style={{ borderColor: 'var(--border-color)' }}>
          <label className="block text-[10px] uppercase mb-2 font-bold tracking-widest" style={{ color: 'var(--text-color)' }}>
            {t.targetDish}
          </label>
          <div className="relative">
            <input 
              type="text"
              onFocus={handleFocus}
              className="w-full border focus:border-opacity-100 p-4 pr-12 text-sm outline-none font-mono"
              style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.targetDishPlace}
              value={formData.targetDish}
              onChange={(e) => updateLocalAndGlobal('targetDish', e.target.value)}
              required
            />
            <MicButton field="targetDish" />
          </div>
        </div>

        <div className="p-4 border" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold tracking-widest" style={{ color: 'var(--text-color)' }}>
             {t.additionalSpecs}
          </label>
          <div className="relative">
            <textarea 
              onFocus={handleFocus}
              className="w-full border p-3 pr-12 text-xs outline-none h-16 font-mono resize-none"
              style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.additionalSpecsPlace}
              value={formData.additionalSpecs}
              onChange={(e) => updateLocalAndGlobal('additionalSpecs', e.target.value)}
            />
            <MicButton field="additionalSpecs" />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="relative">
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.medicalConditions}</label>
            <div className="relative">
              <textarea 
                onFocus={handleFocus}
                className="w-full border p-3 pr-12 text-xs outline-none h-24"
                style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                placeholder={t.medicalConditionsPlace}
                value={formData.medicalConditions}
                onChange={(e) => updateLocalAndGlobal('medicalConditions', e.target.value)}
                required
              />
              <MicButton field="medicalConditions" />
            </div>
          </div>
          <div className="relative">
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.ingredients}</label>
            <div className="relative">
              <textarea 
                onFocus={handleFocus}
                className="w-full border p-3 pr-12 text-xs outline-none h-24"
                style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                placeholder={t.ingredientsPlace}
                value={formData.ingredients}
                onChange={(e) => updateLocalAndGlobal('ingredients', e.target.value)}
              />
              <MicButton field="ingredients" />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="relative">
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.allergies}</label>
            <div className="relative">
              <input 
                type="text"
                onFocus={handleFocus}
                className="w-full border p-3 pr-12 text-xs outline-none"
                style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                placeholder={t.allergiesPlace}
                value={formData.allergies}
                onChange={(e) => updateLocalAndGlobal('allergies', e.target.value)}
              />
              <MicButton field="allergies" />
            </div>
          </div>
          <div className="relative">
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.preferences}</label>
            <div className="relative">
              <input 
                type="text"
                onFocus={handleFocus}
                className="w-full border p-3 pr-12 text-xs outline-none"
                style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                placeholder={t.preferencesPlace}
                value={formData.preferences}
                onChange={(e) => updateLocalAndGlobal('preferences', e.target.value)}
              />
              <MicButton field="preferences" />
            </div>
          </div>
        </div>

        <button 
          disabled={isLoading}
          className="w-full py-5 header-font font-bold text-xs uppercase tracking-[0.4em] transition-all duration-300 border disabled:opacity-30"
          style={{ backgroundColor: 'var(--text-color)', color: 'var(--bg-color)', borderColor: 'var(--text-color)' }}
        >
          {isLoading ? t.processing : t.submitBtn}
        </button>
      </form>
    </div>
  );
};

export default DiagnosticTerminal;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Translations, UserDiagnostics, ChatMessage, DetectedItem } from '../types';
import { analyzeHealthOrMenu } from '../services/geminiService';
import { LANGUAGES } from '../App';

interface Props {
  t: Translations;
  diagnostics: UserDiagnostics;
  onUpdate: (updates: Partial<UserDiagnostics>) => void;
}

const CameraScanner: React.FC<{ onCapture: (base64: string) => void, onClose: () => void, t: Translations }> = ({ onCapture, onClose, t }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError(t.cameraAccessDenied);
      }
    }
    startCamera();

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
        tracks.forEach(track => track.stop());
      }
    };
  }, [t]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(base64);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-4">
      <div className="relative w-full max-w-lg aspect-[3/4] border-2 border-white/20 overflow-hidden bg-black/50">
        {error ? (
          <div className="absolute inset-0 flex items-center justify-center text-center p-6 text-[10px] uppercase tracking-widest text-red-500 font-bold">
            {error}
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            {/* Cyber Overlay */}
            <div className="absolute inset-0 pointer-events-none">
              <div className="absolute top-4 left-4 w-8 h-8 border-l-2 border-t-2 border-white/40"></div>
              <div className="absolute top-4 right-4 w-8 h-8 border-r-2 border-t-2 border-white/40"></div>
              <div className="absolute bottom-4 left-4 w-8 h-8 border-l-2 border-b-2 border-white/40"></div>
              <div className="absolute bottom-4 right-4 w-8 h-8 border-r-2 border-b-2 border-white/40"></div>
              <div className="absolute inset-0 flex items-center justify-center opacity-20">
                <div className="w-48 h-48 border border-dashed border-white rounded-full animate-pulse"></div>
              </div>
              <div className="absolute top-1/2 left-0 w-full h-0.5 bg-green-500/30 animate-[scan_2s_linear_infinite]"></div>
              <div className="absolute top-6 left-1/2 -translate-x-1/2 text-[8px] font-bold tracking-[0.3em] uppercase opacity-60">
                {t.scanningTarget}
              </div>
            </div>
          </>
        )}
      </div>

      <div className="mt-8 flex gap-6">
        <button 
          onClick={onClose}
          className="px-6 py-2 border border-white/20 text-[10px] uppercase font-bold tracking-widest hover:bg-white/10"
          style={{ color: 'var(--text-color)' }}
        >
          {t.cancelBtn}
        </button>
        {!error && (
          <button 
            onClick={capture}
            className="px-8 py-2 bg-white text-black text-[10px] font-bold uppercase tracking-widest hover:scale-105 active:scale-95 transition-all"
          >
            {t.captureData}
          </button>
        )}
      </div>

      <canvas ref={canvasRef} style={{ display: 'none' }} />

      <style>{`
        @keyframes scan {
          0% { transform: translateY(-150px); }
          100% { transform: translateY(150px); }
        }
      `}</style>
    </div>
  );
};

const MenuOverlay: React.FC<{ image: string, detections: DetectedItem[] }> = ({ image, detections }) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'SAFE': return '#22c55e'; // Green
      case 'WARNING': return '#f59e0b'; // Yellow
      case 'FORBIDDEN': return '#ef4444'; // Red
      default: return '#ffffff';
    }
  };

  return (
    <div className="relative w-full border border-white/10 mb-6 bg-black">
      <div className="relative inline-block w-full">
        <img src={image} alt="Menu" className="w-full h-auto block" />
        <svg 
          viewBox="0 0 1000 1000" 
          className="absolute inset-0 w-full h-full pointer-events-auto"
          preserveAspectRatio="none"
        >
          {detections.map((item, idx) => {
            const [ymin, xmin, ymax, xmax] = item.box_2d;
            const color = getStatusColor(item.status);
            return (
              <g 
                key={idx}
                onMouseEnter={() => setHoveredIdx(idx)}
                onMouseLeave={() => setHoveredIdx(null)}
                className="cursor-help"
              >
                <rect
                  x={xmin}
                  y={ymin}
                  width={xmax - xmin}
                  height={ymax - ymin}
                  fill={color}
                  fillOpacity={hoveredIdx === idx ? 0.3 : 0.1}
                  stroke={color}
                  strokeWidth="4"
                  className="transition-all duration-200"
                />
                {hoveredIdx === idx && (
                   <rect
                    x={xmin}
                    y={ymin - 40 < 0 ? ymin : ymin - 40}
                    width="200"
                    height="30"
                    fill="black"
                    stroke={color}
                    strokeWidth="1"
                   />
                )}
                {hoveredIdx === idx && (
                  <text
                    x={xmin + 5}
                    y={ymin - 20 < 20 ? ymin + 20 : ymin - 20}
                    fill="white"
                    fontSize="16"
                    fontWeight="bold"
                    className="pointer-events-none"
                  >
                    {item.name}
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>

      {/* Legenda ed Espansione Dettagli */}
      <div className="p-4 border-t border-white/10 bg-black/40 text-[10px] space-y-3 font-mono">
        <div className="flex gap-4 border-b border-white/5 pb-2 mb-2">
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-green-500"></div> SAFE</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-yellow-500"></div> WARNING</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-red-500"></div> FORBIDDEN</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {detections.map((item, idx) => (
            <div 
              key={idx} 
              className={`p-2 border transition-all ${hoveredIdx === idx ? 'bg-white/5 border-white/40 translate-x-1' : 'border-transparent'}`}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
            >
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5" style={{ backgroundColor: getStatusColor(item.status) }}></div>
                <span className="font-bold uppercase tracking-tighter">{item.name}</span>
              </div>
              <div className="opacity-60 text-[9px] lowercase italic leading-tight">
                // {item.reason}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const QuestionTerminal: React.FC<Props> = ({ t, diagnostics, onUpdate }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeMicField, setActiveMicField] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [localCtx, setLocalCtx] = useState({
    conditions: diagnostics.medicalConditions || '',
    allergies: diagnostics.allergies || '',
    goal: '',
    otherGoal: ''
  });

  // Mantieni localCtx sincronizzato se diagnostics cambia dall'esterno (es. DiagnosticTerminal)
  useEffect(() => {
    setLocalCtx(prev => ({
      ...prev,
      conditions: diagnostics.medicalConditions,
      allergies: diagnostics.allergies
    }));
  }, [diagnostics.medicalConditions, diagnostics.allergies]);

  const isClinicallyValid = localCtx.conditions.trim().length > 0;

  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const handleInputFocus = () => {
    // Ensure the input is visible when keyboard opens on mobile
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const updateField = (field: 'conditions' | 'allergies', value: string) => {
    setLocalCtx(prev => ({ ...prev, [field]: value }));
    onUpdate({ [field === 'conditions' ? 'medicalConditions' : 'allergies']: value });
  };

  const startVoiceInputForField = useCallback((field: 'conditions' | 'allergies' | 'otherGoal') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(field);
    recognition.onend = () => setActiveMicField(null);
    recognition.onerror = () => setActiveMicField(null);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      const currentValue = localCtx[field as keyof typeof localCtx] || '';
      const newValue = currentValue ? `${currentValue} ${transcript}` : transcript;

      if (field === 'conditions' || field === 'allergies') {
        updateField(field, newValue);
      } else {
        setLocalCtx(prev => ({ ...prev, [field]: newValue }));
      }
    };
    recognition.start();
  }, [selectedLang, localCtx]);

  const handleCancelProcessing = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsProcessing(false);
  };

  const handleSend = async (image?: string) => {
    if (!isClinicallyValid) return;

    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);
    setIsCameraOpen(false);

    abortControllerRef.current = new AbortController();

    const finalGoal = localCtx.goal === 'ALTRO' ? localCtx.otherGoal : localCtx.goal;
    const effectiveDiagnostics: UserDiagnostics = {
      ...diagnostics,
      medicalConditions: localCtx.conditions,
      allergies: localCtx.allergies,
      additionalSpecs: finalGoal ? `OBIETTIVO/REGIME: ${finalGoal}. ${diagnostics.additionalSpecs}` : diagnostics.additionalSpecs
    };

    try {
      const result = await analyzeHealthOrMenu(query, effectiveDiagnostics, image);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: result.text, 
        detections: result.detections, 
        image: image,
        sources: result.sources 
      }]);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log('Query aborted by user');
      } else {
        setMessages(prev => [...prev, { role: 'model', text: t.criticalErrorChat }]);
      }
    } finally {
      setIsProcessing(false);
      abortControllerRef.current = null;
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isClinicallyValid) return;
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const MicIcon = ({ isActive }: { isActive: boolean }) => (
    <svg className={`w-3 h-3 ${isActive ? 'recording-pulse' : 'opacity-40 hover:opacity-100 transition-opacity cursor-pointer'}`} fill="currentColor" viewBox="0 0 24 24">
      <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
    </svg>
  );

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {isCameraOpen && <CameraScanner t={t} onClose={() => setIsCameraOpen(false)} onCapture={(b64) => handleSend(b64)} />}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500 bg-black/40">
          <button 
            onClick={handleCancelProcessing}
            className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
            style={{ color: 'var(--text-color)' }}
          >
            <div className="w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all hover:scale-110 active:scale-90 bg-black/10 backdrop-blur-md" style={{ borderColor: 'var(--border-color)' }}>
              <span className="text-2xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
            </div>
            <span className="text-[10px] font-black tracking-[0.2em] uppercase opacity-70 group-hover:opacity-100 transition-opacity">
              {t.cancelBtn}
            </span>
          </button>

          <div className="flex flex-col items-center space-y-12">
            <div className="relative w-40 h-40 flex items-center justify-center">
              <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-3 border-t-2 border-b-2 rounded-full animate-[spin_4s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-6 border-l-2 border-r-2 rounded-full animate-[spin_2s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="w-8 h-8 rounded-full animate-pulse shadow-[0_0_20px_rgba(255,255,255,0.4)]" style={{ backgroundColor: 'var(--text-color)' }}></div>
              <div className="absolute w-full h-0.5 animate-[loading-scan_2.5s_ease-in-out_infinite] opacity-20" style={{ backgroundColor: 'var(--text-color)' }}></div>
            </div>

            <div className="text-center space-y-6 max-w-sm">
              <div className="space-y-2">
                <p className="text-[14px] font-black tracking-[1em] uppercase animate-pulse pr-[-1em]" style={{ color: 'var(--text-color)' }}>
                  {t.loading}
                </p>
                <div className="h-1 w-full bg-white/10 relative overflow-hidden rounded-full">
                  <div className="absolute inset-0 bg-current animate-[loading-progress_3.5s_ease-in-out_infinite]"></div>
                </div>
              </div>
              <p className="text-[10px] opacity-70 uppercase tracking-[0.25em] font-mono leading-relaxed bg-black/5 p-2 rounded backdrop-blur-sm">
                {t.analysisClinicalParams}<br/>
                {t.syncDiagnosticMatrix}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className={`glow-border p-4 bg-black/20 border-2 ${!isClinicallyValid ? 'border-red-500/50 animate-pulse' : ''}`} style={{ borderColor: isClinicallyValid ? 'var(--border-color)' : undefined }}>
          <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
            <span className={`w-1 h-1 rounded-full ${!isClinicallyValid ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></span>
            {t.activeClinicalProfile} {!isClinicallyValid && "[DATA_REQUIRED]"}
          </div>
          <div className="space-y-3">
            <div className="relative group">
              <input type="text" placeholder={t.medicalConditionsPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.conditions} onChange={(e) => updateField('conditions', e.target.value)} />
              <button type="button" onClick={() => startVoiceInputForField('conditions')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'conditions'} /></button>
            </div>
            <div className="relative group">
              <input type="text" placeholder={t.allergiesPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/10 text-[10px] py-1 pr-6 outline-none focus:border-white/30 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.allergies} onChange={(e) => updateField('allergies', e.target.value)} />
              <button type="button" onClick={() => startVoiceInputForField('allergies')} className="absolute right-0 top-1/2 -translate-y-1/2"><MicIcon isActive={activeMicField === 'allergies'} /></button>
            </div>
          </div>
        </div>
        <div className="glow-border p-4 bg-black/20 flex flex-col justify-between" style={{ borderColor: 'var(--border-color)' }}>
          <div>
            <div className="text-[8px] font-bold uppercase tracking-[0.2em] mb-3 opacity-50 flex items-center gap-2">
              <span className="w-1 h-1 bg-blue-500 rounded-full"></span>
              {t.goalsAndRegimes}
            </div>
            <select className="w-full bg-transparent border border-white/10 text-[10px] p-2 outline-none hover:bg-white/5 transition-all uppercase font-mono cursor-pointer" style={{ color: 'var(--text-color)' }} value={localCtx.goal} onChange={(e) => setLocalCtx({...localCtx, goal: e.target.value})}>
              <option value="" className="bg-black">{t.selectGoal}</option>
              <option value="PERDITA_PESO" className="bg-black">{t.goalWeightLoss}</option>
              <option value="MASSA_MUSCOLARE" className="bg-black">{t.goalMuscleMass}</option>
              <option value="CONTROLLO_GLICEMICO" className="bg-black">{t.goalGlycemicControl}</option>
              <option value="VEGANO" className="bg-black">{t.goalVegan}</option>
              <option value="PESCATARIANO" className="bg-black">{t.goalPescatarian}</option>
              <option value="MUSULMANO" className="bg-black">{t.goalMuslim}</option>
              <option value="ANTI_INFIAMMATORIO" className="bg-black">{t.goalAntiInflammatory}</option>
              <option value="ALTRO" className="bg-black">{t.goalOther}</option>
            </select>
          </div>
        </div>
      </div>

      <div className="glow-border flex flex-col min-h-[400px] h-[60vh] rounded-none overflow-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
        <div className="border-b p-4 flex justify-between items-center flex-wrap gap-4" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <h2 className="header-font text-xs font-bold tracking-[0.2em] uppercase" style={{ color: 'var(--text-color)' }}>{t.healthCenter}</h2>

          {/* Highlighted Scan Buttons */}
          <div className={`flex gap-3 transition-all duration-300 ${!isClinicallyValid ? 'opacity-20 pointer-events-none grayscale' : 'opacity-100'}`}>
            <button 
              onClick={() => setIsCameraOpen(true)} 
              className="px-4 py-2 bg-white text-black text-[10px] font-black uppercase flex items-center gap-2 shadow-[0_0_15px_rgba(255,255,255,0.3)] hover:scale-105 transition-all active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                <circle cx="12" cy="13" r="3" strokeWidth={2.5} />
              </svg>
              {t.liveScan}
            </button>

            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="px-4 py-2 border-2 text-[10px] font-black uppercase flex items-center gap-2 hover:bg-white hover:text-black transition-all active:scale-95" 
              style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              {t.uploadMenu}
            </button>
          </div>
          <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleFileUpload} />
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 font-mono custom-scrollbar">
          {messages.length === 0 && !isClinicallyValid && (
             <div className="flex flex-col items-center justify-center h-full space-y-4 opacity-40">
                <svg className="w-12 h-12 text-red-500 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
                <p className="text-[10px] uppercase font-bold tracking-[0.2em] text-center max-w-xs">
                  [WARNING: SYSTEM_LOCKED]<br/>
                  PLEASE SPECIFY MEDICAL CONDITIONS ABOVE TO INITIALIZE DIAGNOSTIC SENSORS
                </p>
             </div>
          )}

          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 border ${msg.role === 'user' ? 'bg-white text-black' : ''}`} style={{ borderColor: 'var(--border-color)' }}>
                <div className="text-[7px] uppercase font-bold mb-2 opacity-50 border-b pb-1">
                  {msg.role === 'user' ? t.unitPilot : t.chefOmoikaneLabel}
                </div>
                {msg.image && msg.detections ? (
                   <MenuOverlay image={msg.image} detections={msg.detections} />
                ) : msg.image && (
                   <img src={msg.image} alt="User Upload" className="mb-4 max-w-full border p-1" style={{ borderColor: 'var(--border-color)' }} />
                )}
                <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.text}</div>

                {/* Visualizzazione Sorgenti Web */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10">
                    <div className="text-[8px] font-bold uppercase tracking-widest opacity-50 mb-2">{t.webSources}</div>
                    <div className="flex flex-col gap-2">
                      {msg.sources.map((source, sIdx) => (
                        <a 
                          key={sIdx} 
                          href={source.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-[9px] text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-1 group"
                        >
                          <svg className="w-2.5 h-2.5 opacity-40 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          <span className="truncate max-w-xs">{source.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={scrollRef} />
        </div>

        <form 
          ref={formRef}
          onSubmit={(e) => { e.preventDefault(); handleSend(); }} 
          className="p-4 border-t flex gap-4" 
          style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}
        >
          <div className="flex-1 relative flex items-center">
            <span className="mr-3 opacity-30">{'>'}</span>
            <input 
              ref={inputRef}
              type="text" 
              className={`flex-1 bg-transparent outline-none text-sm font-mono transition-opacity duration-300 ${!isClinicallyValid ? 'opacity-20' : 'opacity-100'}`} 
              style={{ color: 'var(--text-color)' }} 
              placeholder={isClinicallyValid ? t.chatPlaceholder : "[SYSTEM_LOCKED] ENTER CONDITIONS FIRST"} 
              value={input} 
              onFocus={handleInputFocus}
              onChange={(e) => setInput(e.target.value)} 
              disabled={isProcessing || !isClinicallyValid} 
            />
          </div>
          <button 
            type="submit" 
            disabled={isProcessing || !input.trim() || !isClinicallyValid} 
            className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase disabled:opacity-20 transition-all active:scale-95"
          >
            {t.send}
          </button>
        </form>
      </div>
    </div>
  );
};

