                      style={language === lang.code ? { backgroundColor: 'var(--text-color)', color: 'var(--bg-color)' } : { color: 'var(--text-color)' }}
                    >
                      <span>{lang.flag} {lang.label}</span>
                      {language === lang.code && <span className="text-[7px]">●</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

