            {t.activeClinicalProfile}
          </div>
          <div className="space-y-4">
            <div className="relative group">
              <input type="text" placeholder={t.medicalConditionsPlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/20 text-xs py-2 pr-8 outline-none focus:border-white/40 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.conditions} onChange={(e) => updateField('conditions', e.target.value)} />
              <button type="button" onClick={() => startVoiceInputForField('conditions')} className="absolute right-0 top-1/2 -translate-y-1/2" title="REC_SENSOR"><MicIcon isActive={activeMicField === 'conditions'} /></button>
