export const analyzeHealthOrMenu = async (
  query: string, 
  diagnostics: UserDiagnostics, 
  imageBase64?: string
): Promise<{ text: string, detections?: DetectedItem[], sources?: { title: string, uri: string }[] }> => {
  const parts: any[] = [{ text: query }];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64.split(',')[1],
        mimeType: "image/jpeg"
      }
    });
  }

  const t = i18n[diagnostics.language];
  const medicalInfo = diagnostics.medicalConditions.trim() || t.healthyStatus;
  const prompt = `Analisi basata su:\nQuery: ${query}\nCondizioni mediche: ${medicalInfo}\nAllergie: ${diagnostics.allergies}\nObiettivi/Regimi: ${diagnostics.additionalSpecs}\n\nEsegui un'analisi nutrizionale dei piatti. Se l'utente è sano, focalizzati su zuccheri, sodio e grassi saturi. Se l'immagine mostra un prodotto commerciale, cerca su Google i suoi valori nutrizionali reali. Usa detections per indicare visivamente la salubrità con i colori.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: [...parts, { text: prompt }] },
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: { type: Type.STRING, description: "Analisi testuale dettagliata che spiega perché un cibo è sano o meno." },
          detections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                status: { type: Type.STRING, enum: ['SAFE', 'WARNING', 'FORBIDDEN'] },
                box_2d: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                reason: { type: Type.STRING }
              },
              required: ["name", "status", "box_2d", "reason"]
            }
          }
        },
        required: ["text"]
      }
    }
  });

  const parsed = JSON.parse(response.text);

  // Estrai le sorgenti dal grounding metadata
  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => {
      if (chunk.web) {
        return {
          title: chunk.web.title || 'Source',
          uri: chunk.web.uri || ''
        };
      }
      return null;
    })
    ?.filter(Boolean) as { title: string; uri: string }[] || [];

  return {
    text: parsed.text,
    detections: parsed.detections,
    sources: sources.length > 0 ? sources : undefined
  };
};

