const CameraScanner: React.FC<{ onCapture: (base64: string) => void, onClose: () => void, t: Translations }> = ({ onCapture, onClose, t }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError(t.cameraAccessDenied);
      }
    }
    startCamera();

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
        tracks.forEach(track => track.stop());
      }
    };
  }, [t]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(base64);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-4">
      <div className="relative w-full max-w-lg aspect-[3/4] border-2 border-white/20 overflow-hidden bg-black/50">
        {error ? (
          <div className="absolute inset-0 flex items-center justify-center text-center p-6 text-[10px] uppercase tracking-widest text-red-500 font-bold">
            {error}
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            {/* Cyber Overlay */}
            <div className="absolute inset-0 pointer-events-none">
              <div className="absolute top-4 left-4 w-8 h-8 border-l-2 border-t-2 border-white/40"></div>
              <div className="absolute top-4 right-4 w-8 h-8 border-r-2 border-t-2 border-white/40"></div>
              <div className="absolute bottom-4 left-4 w-8 h-8 border-l-2 border-b-2 border-white/40"></div>
              <div className="absolute bottom-4 right-4 w-8 h-8 border-r-2 border-b-2 border-white/40"></div>
              <div className="absolute inset-0 flex items-center justify-center opacity-20">
                <div className="w-48 h-48 border border-dashed border-white rounded-full animate-pulse"></div>
              </div>
              <div className="absolute top-1/2 left-0 w-full h-0.5 bg-green-500/30 animate-[scan_2s_linear_infinite]"></div>

              {/* TESTO SUPERIORE RIFORMULATO */}
              <div className="absolute top-6 left-0 w-full text-center px-4">
                 <div className="inline-block bg-black/60 backdrop-blur-md px-4 py-2 border border-white/10">
                    <span className="text-[10px] font-black tracking-[0.2em] uppercase text-white animate-pulse">
                      {t.scanningTarget}
                    </span>
                 </div>
              </div>
            </div>
          </>
        )}
      </div>

      <div className="mt-8 flex flex-col items-center gap-4">
        <div className="flex gap-6">
          <button 
            onClick={onClose}
            className="px-6 py-2 border border-white/20 text-[10px] uppercase font-bold tracking-widest hover:bg-white/10"
            style={{ color: 'var(--text-color)' }}
          >
            {t.cancelBtn}
          </button>
          {!error && (
            <button 
              onClick={capture}
              className="px-8 py-2 bg-white text-black text-[10px] font-bold uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-[0_0_20px_rgba(255,255,255,0.4)]"
            >
              {t.captureData}
            </button>
          )}
        </div>

        {/* ISTRUZIONE SOTTO IL PULSANTE */}
        {!error && (
          <div className="text-[9px] uppercase tracking-[0.2em] opacity-50 font-mono animate-pulse">
            {t.pressToScan}
          </div>
        )}
      </div>

      <canvas ref={canvasRef} style={{ display: 'none' }} />

      <style>{`
        @keyframes scan {
          0% { transform: translateY(-150px); }
          100% { transform: translateY(150px); }
        }
      `}</style>
    </div>
  );
};

const MenuOverlay: React.FC<{ image: string, detections: DetectedItem[] }> = ({ image, detections }) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'SAFE': return '#22c55e'; // Green
      case 'WARNING': return '#f59e0b'; // Yellow
      case 'FORBIDDEN': return '#ef4444'; // Red
      default: return '#ffffff';
    }
  };

  return (
    <div className="relative w-full border border-white/10 mb-6 bg-black">
      <div className="relative inline-block w-full">
        <img src={image} alt="Menu" className="w-full h-auto block" />
        <svg 
          viewBox="0 0 1000 1000" 
          className="absolute inset-0 w-full h-full pointer-events-auto"
          preserveAspectRatio="none"
        >
          {detections.map((item, idx) => {
            const [ymin, xmin, ymax, xmax] = item.box_2d;
            const color = getStatusColor(item.status);
            return (
              <g 
                key={idx}
                onMouseEnter={() => setHoveredIdx(idx)}
                onMouseLeave={() => setHoveredIdx(null)}
                className="cursor-help"
              >
                <rect
                  x={xmin}
                  y={ymin}
                  width={xmax - xmin}
                  height={ymax - ymin}
                  fill={color}
                  fillOpacity={hoveredIdx === idx ? 0.3 : 0.1}
                  stroke={color}
                  strokeWidth="4"
                  className="transition-all duration-200"
                />
                {hoveredIdx === idx && (
                   <rect
                    x={xmin}
                    y={ymin - 40 < 0 ? ymin : ymin - 40}
                    width="200"
                    height="30"
                    fill="black"
                    stroke={color}
                    strokeWidth="1"
                   />
                )}
                {hoveredIdx === idx && (
                  <text
                    x={xmin + 5}
                    y={ymin - 20 < 20 ? ymin + 20 : ymin - 20}
                    fill="white"
                    fontSize="16"
                    fontWeight="bold"
                    className="pointer-events-none"
                  >
                    {item.name}
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>

      {/* Legenda ed Espansione Dettagli */}
      <div className="p-4 border-t border-white/10 bg-black/40 text-[10px] space-y-3 font-mono">
        <div className="flex gap-4 border-b border-white/5 pb-2 mb-2">
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-green-500"></div> SAFE</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-yellow-500"></div> WARNING</div>
          <div className="flex items-center gap-2"><div className="w-2 h-2 bg-red-500"></div> FORBIDDEN</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {detections.map((item, idx) => (
            <div 
              key={idx} 
              className={`p-2 border transition-all ${hoveredIdx === idx ? 'bg-white/5 border-white/40 translate-x-1' : 'border-transparent'}`}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
            >
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5" style={{ backgroundColor: getStatusColor(item.status) }}></div>
                <span className="font-bold uppercase tracking-tighter">{item.name}</span>
              </div>
              <div className="opacity-60 text-[9px] lowercase italic leading-tight">
                // {item.reason}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const QuestionTerminal: React.FC<Props> = ({ t, diagnostics, onUpdate }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeMicField, setActiveMicField] = useState<boolean>(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [localCtx, setLocalCtx] = useState({
    healthProfile: diagnostics.healthProfile || '',
  });

  useEffect(() => {
    setLocalCtx({
      healthProfile: diagnostics.healthProfile
    });
  }, [diagnostics.healthProfile]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const handleInputFocus = () => {
    setTimeout(() => {
      formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const updateField = (value: string) => {
    setLocalCtx({ healthProfile: value });
    onUpdate({ healthProfile: value });
  };

  const startVoiceInput = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(true);
    recognition.onend = () => setActiveMicField(false);
    recognition.onerror = () => setActiveMicField(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      const currentValue = localCtx.healthProfile || '';
      const newValue = currentValue ? `${currentValue} ${transcript}` : transcript;
      updateField(newValue);
    };
    recognition.start();
  }, [selectedLang, localCtx]);

  const handleCancelProcessing = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsProcessing(false);
  };

  const handleSend = async (image?: string) => {
    const query = input.trim() || (image ? t.menuAnalysisRequest : '');
    if (!query && !image) return;

    const userMsg: ChatMessage = { role: 'user', text: query, image };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);
    setIsCameraOpen(false);

    abortControllerRef.current = new AbortController();

    const effectiveDiagnostics: UserDiagnostics = {
      ...diagnostics,
      healthProfile: localCtx.healthProfile
    };

    try {
      const result = await analyzeHealthOrMenu(query, effectiveDiagnostics, image);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: result.text, 
        detections: result.detections, 
        image: image,
        sources: result.sources 
      }]);
    } catch (err: any) {
      if (err.name === 'AbortError') {
        console.log(t.abortMessage);
      } else {
        setMessages(prev => [...prev, { role: 'model', text: t.criticalErrorChat }]);
      }
    } finally {
      setIsProcessing(false);
      abortControllerRef.current = null;
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleSend(base64);
    };
    reader.readAsDataURL(file);
  };

  const MicButton = ({ isActive }: { isActive: boolean }) => (
    <button
      type="button"
      onClick={startVoiceInput}
      className={`absolute right-0 top-1/2 -translate-y-1/2 transition-all p-3 flex items-center justify-center rounded-full hover:bg-white/10 ${isActive ? 'recording-pulse scale-110' : 'opacity-40 hover:opacity-100'}`}
      title="REC_SENSOR"
    >
      <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24">
        <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
      </svg>
    </button>
  );

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {isCameraOpen && <CameraScanner t={t} onClose={() => setIsCameraOpen(false)} onCapture={(b64) => handleSend(b64)} />}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center backdrop-blur-2xl animate-in fade-in duration-500 bg-black/40">
          <button 
            onClick={handleCancelProcessing}
            className="absolute top-10 right-10 flex flex-col items-center gap-2 group"
            style={{ color: 'var(--text-color)' }}
          >
            <div className="w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all hover:scale-110 active:scale-90 bg-black/10 backdrop-blur-md" style={{ borderColor: 'var(--border-color)' }}>
              <span className="text-2xl font-light group-hover:rotate-90 transition-transform duration-300">✕</span>
            </div>
            <span className="text-[10px] font-black tracking-[0.2em] uppercase opacity-70 group-hover:opacity-100 transition-opacity">
              {t.cancelBtn}
            </span>
          </button>

          <div className="flex flex-col items-center space-y-12">
            <div className="relative w-40 h-40 flex items-center justify-center">
              <div className="absolute inset-0 border-2 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-20" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-3 border-t-2 border-b-2 rounded-full animate-[spin_4s_linear_infinite]" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="absolute inset-6 border-l-2 border-r-2 rounded-full animate-[spin_2s_linear_infinite] opacity-60" style={{ borderColor: 'var(--text-color)' }}></div>
              <div className="w-8 h-8 rounded-full animate-pulse shadow-[0_0_20px_rgba(255,255,255,0.4)]" style={{ backgroundColor: 'var(--text-color)' }}></div>
              <div className="absolute w-full h-0.5 animate-[loading-scan_2.5s_ease-in-out_infinite] opacity-20" style={{ backgroundColor: 'var(--text-color)' }}></div>
            </div>

            <div className="text-center space-y-6 max-w-sm">
              <div className="space-y-2">
                <p className="text-[14px] font-black tracking-[1em] uppercase animate-pulse pr-[-1em]" style={{ color: 'var(--text-color)' }}>
                  {t.loading}
                </p>
                <div className="h-1 w-full bg-white/10 relative overflow-hidden rounded-full">
                  <div className="absolute inset-0 bg-current animate-[loading-progress_3.5s_ease-in-out_infinite]"></div>
                </div>
              </div>
              <p className="text-[10px] opacity-70 uppercase tracking-[0.25em] font-mono leading-relaxed bg-black/5 p-2 rounded backdrop-blur-sm">
                {t.analysisClinicalParams}<br/>
                {t.syncDiagnosticMatrix}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        <div className="glow-border p-6 bg-black/20 border-2" style={{ borderColor: 'var(--border-color)' }}>
          <div className="text-[10px] font-bold uppercase tracking-[0.2em] mb-4 opacity-50 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-green-500"></span>
            {t.activeClinicalProfile}
          </div>
          <div className="space-y-4">
            <div className="relative group">
              <input type="text" placeholder={t.healthProfilePlace} onFocus={handleInputFocus} className="w-full bg-transparent border-b border-white/20 text-xs py-4 pr-16 outline-none focus:border-white/40 transition-colors uppercase font-mono" style={{ color: 'var(--text-color)' }} value={localCtx.healthProfile} onChange={(e) => updateField(e.target.value)} />
              <MicButton isActive={activeMicField} />
            </div>
          </div>
        </div>
      </div>

      <div className="glow-border flex flex-col min-h-[450px] h-[65vh] rounded-none overflow-hidden" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
        <div className="border-b p-4 flex justify-between items-center flex-wrap gap-4" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <h2 className="header-font text-xs font-bold tracking-[0.2em] uppercase" style={{ color: 'var(--text-color)' }}>{t.healthCenter}</h2>

          <div className="flex gap-3 transition-all duration-300">
            <button 
              onClick={() => setIsCameraOpen(true)} 
              className="px-4 py-2 bg-white text-black text-[10px] font-black uppercase flex items-center gap-2 shadow-[0_0_15px_rgba(255,255,255,0.3)] hover:scale-105 transition-all active:scale-95"
              title="START_VISUAL_SENSOR"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                <circle cx="12" cy="13" r="3" strokeWidth={2.5} />
              </svg>
              {t.liveScan}
            </button>

            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="px-4 py-2 border-2 text-[10px] font-black uppercase flex items-center gap-2 hover:bg-white hover:text-black transition-all active:scale-95" 
              style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}
              title="IMPORT_DATA_MATRIX"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              {t.uploadMenu}
            </button>
          </div>
          <input type="file" ref={fileInputRef} hidden accept="image/*,application/pdf" onChange={handleFileUpload} />
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 font-mono custom-scrollbar">
          {messages.length === 0 && (
             <div className="flex flex-col items-center justify-center h-full space-y-4 opacity-40">
                <div className="w-16 h-16 border-2 border-dashed flex items-center justify-center animate-pulse" style={{ borderColor: 'var(--border-color)' }}>
                   <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                  </svg>
                </div>
                <div className="text-center space-y-2">
                  <p className="text-[12px] uppercase font-bold tracking-[0.2em]" style={{ color: 'var(--text-color)' }}>
                    {t.systemLocked}
                  </p>
                  <p className="text-[9px] uppercase tracking-[0.1em] leading-relaxed max-w-xs mx-auto opacity-70">
                    {t.enterConditionsPrompt}
                  </p>
                </div>
             </div>
          )}

          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 border ${msg.role === 'user' ? 'bg-white text-black' : ''}`} style={{ borderColor: 'var(--border-color)' }}>
                <div className="text-[7px] uppercase font-bold mb-2 opacity-50 border-b pb-1">
                  {msg.role === 'user' ? t.unitPilot : t.chefOmoikaneLabel}
                </div>
                {msg.image && msg.detections ? (
                   <MenuOverlay image={msg.image} detections={msg.detections} />
                ) : msg.image && (
                   <img src={msg.image} alt="User Upload" className="mb-4 max-w-full border p-1" style={{ borderColor: 'var(--border-color)' }} />
                )}
                <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.text}</div>

                {/* Visualizzazione Sorgenti Web */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10">
                    <div className="text-[8px] font-bold uppercase tracking-widest opacity-50 mb-2">{t.webSources}</div>
                    <div className="flex flex-col gap-2">
                      {msg.sources.map((source, sIdx) => (
                        <a 
                          key={sIdx} 
                          href={source.uri} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-[9px] text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-1 group"
                        >
                          <svg className="w-2.5 h-2.5 opacity-40 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                          <span className="truncate max-w-xs">{source.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={scrollRef} />
        </div>

        <form 
          ref={formRef}
          onSubmit={(e) => { e.preventDefault(); handleSend(); }} 
          className="p-4 border-t flex gap-4" 
          style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}
        >
          <div className="flex-1 relative flex items-center">
            <span className="mr-3 opacity-30">{'>'}</span>
            <input 
              ref={inputRef}
              type="text" 
              className="flex-1 bg-transparent outline-none text-sm font-mono opacity-100" 
              style={{ color: 'var(--text-color)' }} 
              placeholder={t.chatPlaceholder} 
              value={input} 
              onFocus={handleInputFocus}
              onChange={(e) => setInput(e.target.value)} 
              disabled={isProcessing} 
            />
          </div>
          <button 
            type="submit" 
            disabled={isProcessing || !input.trim()} 
            className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase disabled:opacity-20 transition-all active:scale-95"
          >
            {t.send}
          </button>
        </form>
      </div>
    </div>
  );
};

export default QuestionTerminal;

import React, { useState } from 'react';
import { Translations, AppTheme, AppLanguage, AppView } from '../types';
import { LANGUAGES } from '../App';

interface Props {
  t: Translations;
  theme: AppTheme;
  onThemeToggle: () => void;
  language: AppLanguage;
  setLanguage: (lang: AppLanguage) => void;
  currentView: AppView;
  setView: (view: AppView) => void;
  onHelpOpen: () => void;
}

const TerminalHeader: React.FC<Props> = ({ 
  t, 
  theme, 
  onThemeToggle, 
  language, 
  setLanguage, 
  currentView, 
  setView, 
  onHelpOpen
}) => {
  const [isLangOpen, setIsLangOpen] = useState(false);
  const selectedLang = LANGUAGES.find(l => l.code === language);

  return (
    <header className="py-6 border-b border-white/20 theme-transition sticky top-0 z-50 backdrop-blur-md" style={{ backgroundColor: 'var(--header-bg)' }}>
      <div className="container mx-auto px-4 flex justify-between items-start">
        {/* Left Side: Title + Nav Buttons Stacked */}
